insert into public.content (collection, slug, data, status) values
('briefs', 'gendering-the-green-transition', $rita${"title":"Gendering the green transition","number":4,"programme":"IND","authors":["Gideon Ndubuisi","Elvis Korku Avenyo","Shingie Chisoro"],"basedOn":["gendering-structural-change-and-green-transition-in-africa-implications","gendering-green-transition-in-africa-implications-of-transformative"],"date":"2024-10","recommendations":[{"text":"Put gender at the centre of industrial policy with a gender-transformative industrial policy framework (G-TRIP).","why":"Structural change in Africa has tended to widen gender employment gaps."},{"text":"Expand women’s economic opportunities and social standing alongside industrial and green policy.","why":"Countries with such policies offset the negative effect of structural change on gender balance."},{"text":"Open green energy and transition-technology jobs to women by tackling the inequalities that keep them out.","why":"These sectors offer gender-balanced employment, but entrenched inequalities stand in the way."}],"issue":"Africa’s structural transformation and green transition are reshaping who works where. Without deliberate policy, the shift risks leaving women behind.","evidence":"Panel data for 48 African countries from 1992 to 2019 show that shifts in sectoral composition have tended to worsen gender employment balance. Policies that expand women’s economic opportunities offset this effect.\n\nCase studies of Ghana and South Africa show that green energy systems and transition technologies create room for more gender-balanced employment, but entrenched gender inequalities are a major obstacle.","pdf":"https://egc.yale.edu/sites/default/files/2024-10/ACET_Gendering_Structural_Change_and_Green_Transition_in_Africa.pdf","sources":["https://egc.yale.edu/sites/default/files/2024-10/ACET_Gendering_Structural_Change_and_Green_Transition_in_Africa.pdf","https://cris.maastrichtuniversity.nl/en/publications/gendering-green-transition-in-africa-implications-of-transformati/","https://econpapers.repec.org/RePEc:unm:unumer:2026011","https://www.wits.ac.za/events-archive/scis/gendering-structural-change-and-green-transition-in-africa-implications-of-transformative-policies.php"]}$rita$::jsonb, 'published'),
('briefs', 'gvcs-job-creation-and-job-destruction', $rita${"title":"GVCs, job creation and job destruction","number":6,"programme":"INN","authors":["Gideon Ndubuisi","Solomon Owusu"],"basedOn":["opeds:global-value-chains-job-creation-and-job-destruction-among-firms-in","global-value-chains-job-creation-and-job-destruction-among-firms-in"],"date":"2026-03","recommendations":[{"text":"Help new, small and young firms enter global value chains.","why":"Net job gains from GVC integration are driven by firms entering GVCs, largely younger and smaller ones."},{"text":"Pair GVC promotion with support for workers in firms that already trade in GVCs.","why":"Continuing GVC firms show an overall net job loss, so the job effects are uneven."},{"text":"Judge GVC policy on jobs as well as productivity.","why":"The full welfare effect of GVC trade depends on both productivity gains and net job reallocation."}],"issue":"Global value chains can raise productivity, but the technologies they bring may save labour. For South Africa, with very high unemployment, the question is whether GVC integration creates jobs or leads to jobless growth.","evidence":"Using administrative data on the universe of formal manufacturing firms from the South African Revenue Service and National Treasury, the study finds that GVC integration is linked to net job gains at the firm level, through job reallocation. The gains are driven by firms entering GVCs, largely younger and smaller firms. Firms that continuously participate in GVCs show an overall net job loss.","pdf":"https://steg.cepr.org/sites/default/files/2023-08/WP073%20NdubuisiOwusuGlobalValueChainsJobCreation.pdf","sources":["https://grp.cepr.org/publications/steg-policy-brief/global-value-chains-job-creation-and-job-destruction-among-firms","https://cepr.org/publications/wp073","https://grp.cepr.org/steg/projects/global-value-chains-job-creation-and-job-destruction-among-firms-south-africa"]}$rita$::jsonb, 'published'),
('briefs', 'keeping-industry-running-electricity-crises-and-south-african', $rita${"title":"Keeping industry running: electricity crises and South African manufacturing","number":2,"programme":"EN","authors":["Gideon Ndubuisi","Elvis Korku Avenyo","Rex Asiama"],"basedOn":["jobs-investments-and-exporting-the-real-effects-of-electricity-crises","dancing-on-the-grid-electricity-crises-manufacturing-energy"],"date":"2026","recommendations":[{"text":"Treat reliable electricity as productive infrastructure for industry, not only as a utility service.","why":"Outages destroyed jobs, lowered capital investment and disrupted exports of manufacturing firms."},{"text":"Target support at the most energy-vulnerable manufacturing sub-sectors.","why":"Job losses were largest in sectors with higher energy vulnerability, in both formal and informal work."},{"text":"Rebuild lost capabilities, not just lost power, in South Africa’s green transition.","why":"Restoring supply does not restore the skills, investment and export links that firms lost during the crises."}],"issue":"Since 2007, South Africa’s electricity crises have disrupted production across manufacturing. Repeated outages make it costlier to keep workers, delay investment and push firms into expensive backup power. Power has now returned, but the damage to industry remains.","evidence":"Using South Africa’s input–output matrices, the authors build an index of manufacturing sub-sector energy vulnerability. It shows large differences across sub-sectors. Electricity crises are linked to significant job losses, and the damage is greatest in the most energy-vulnerable sectors, for formal and informal jobs alike.\n\nFirm-level evidence shows the crises also lowered capital investment and upended export activity. Ownership structure, firm age, size and financial status shape how hard firms are hit.","pdf":"https://repository.tudelft.nl/file/File_2c5d23b2-81b6-465e-b966-0b0696134767","sources":["https://doi.org/10.1016/j.eneco.2026.109234","https://doi.org/10.1016/j.enpol.2025.114534","https://ideas.repec.org/p/unu/wpaper/wp-2024-41.html","https://sa-tied.wider.unu.edu/article/jobs-investments-and-exporting-the-real-effects-of-electricity-crises-in-south-africa","https://africanarguments.org/?p=48463"]}$rita$::jsonb, 'published'),
('briefs', 'no-chips-no-power-africa-and-the-semiconductor-value-chain', $rita${"title":"No chips, no power: Africa and the semiconductor value chain","number":5,"programme":"INN","authors":["Gideon Ndubuisi"],"basedOn":["opeds:no-chips-no-power-why-africa-must-enter-the-global-semiconductor-value"],"date":"2026-02","recommendations":[{"text":"Enter the semiconductor value chain through feasible segments: chip design, assembly, testing and packaging, and power electronics.","why":"Fabrication needs capital, infrastructure and reliable energy that Africa lacks today; these segments need far less."},{"text":"Enter collectively, using the AfCFTA.","why":"No single African market is large enough on its own."},{"text":"Link Africa’s critical minerals to chip-related production rather than exporting them raw.","why":"Africa holds a large share of the minerals used in chips but contributes less than 1% of global semiconductor output."}],"issue":"Chips run everything from cars to clinics to the power grid. Africa supplies many of the critical minerals used to make them, but accounts for less than 1% of global semiconductor output.","evidence":"Fabrication is highly capital-intensive and needs advanced infrastructure, industrial water and reliable power. Chip design does not require a fabrication plant, and assembly, testing and packaging need much lower investment. Countries such as Morocco, Nigeria, Kenya and Rwanda are already moving into these segments.","pdf":"https://www.gdadvisory.org/_files/ugd/aeda26_794d17f3e3c44834ae6d49940b25e8c4.pdf","sources":["https://www.gdadvisory.org/_files/ugd/aeda26_794d17f3e3c44834ae6d49940b25e8c4.pdf","https://aasciences.africa/news/africa-semiconductor-forum-sets-path-from-minerals-to-microchips","https://www.weforum.org/stories/supply-chains-and-transportation/african-nations-hubs-global-semiconductor-supply-chain/","https://www.ecofinagency.com/news-industry/0609-58657-semiconductors-mapping-africa-s-capabilities-across-the-value-chain"]}$rita$::jsonb, 'published'),
('briefs', 'regional-mineral-value-chains-why-africa-must-coordinate', $rita${"title":"Regional mineral value chains: why Africa must coordinate","number":1,"programme":"MIN","authors":["Gideon Ndubuisi","Elvis Korku Avenyo","Solomon Owusu","Woubet Kassa"],"basedOn":["regionalizing-green-transition-minerals-for-structural-transformation","opeds:africas-mineral-strength-is-wasted-if-countries-dont-work-together"],"date":"2025-10","recommendations":[{"text":"Pool mineral supplies, infrastructure and skills across borders.","why":"Small national volumes make it hard for any one country to influence buyers or attract large processing plants; pooling lowers costs and strengthens negotiating power."},{"text":"Make processing, technology transfer and worker training part of every mineral partnership.","why":"Partnerships with foreign governments and companies should go beyond extracting and exporting minerals."},{"text":"Use the AfCFTA to build intra-African mineral value chains, backed by shared infrastructure and harmonised standards.","why":"No single country holds every input; regional coordination turns geology into value chains."}],"issue":"Africa has deposits, reserves or production of at least one transition mineral in 48 countries, yet it exports most of them raw. Limited local processing, weak industrialisation and heavy dependence on Asian buyers, especially China, mean the continent captures little of the value its minerals create.","evidence":"The World Bank–commissioned study maps 41 minerals used in bioenergy, electricity networks, batteries, energy storage, electric vehicles and carbon capture. South Africa alone holds 24 of them. Local refining raises value sharply: Congolese cobalt sells for about US$5.80 per kilogram at extraction and US$16.20 after local refining.\n\nThe study reviews national and regional mineral and industrial policies and finds them fragmented. It concludes that only deeper regional cooperation, shared infrastructure and coordinated policy can turn mineral wealth into broad-based prosperity.","pdf":"https://documents1.worldbank.org/curated/en/099620011192519026/pdf/IDU-959b6025-1de2-4caf-98be-9c8aa42577da.pdf","sources":["https://documents1.worldbank.org/curated/en/099620011192519026/pdf/IDU-959b6025-1de2-4caf-98be-9c8aa42577da.pdf","https://theconversation.com/africas-mineral-strength-is-wasted-if-countries-dont-work-together-new-report-290306","https://www.downtoearth.org.in/africa/africas-mineral-strength-is-wasted-if-countries-dont-work-together-new-report","https://www.moneyweb.co.za/news/africa/africas-mineral-strength-is-wasted-if-countries-dont-work-together-new-report/"]}$rita$::jsonb, 'published'),
('briefs', 'solar-pv-manufacturing-in-africa-opportunity-or-mirage', $rita${"title":"Solar PV manufacturing in Africa: opportunity or mirage?","number":3,"programme":"EN","authors":["Gideon Ndubuisi","Elvis Korku Avenyo"],"basedOn":["solar-photovoltaic-manufacturing-in-africa-opportunity-or-mirage"],"date":"2024-07","recommendations":[{"text":"Adopt a regionalised solar PV strategy for Africa.","why":"Without a coordinated approach, individual countries are unlikely to integrate into the global solar market."},{"text":"Consolidate the continent’s minerals, technological capacities and investment into one integrated PV value chain across countries.","why":"Most countries lack the finance, technology and infrastructure to build a competitive sector alone."},{"text":"Divide the chain by strength: mineral-rich countries such as the DRC and Zambia focus on extraction and processing, others on later stages.","why":"Each African country exports at least one key solar raw material, mostly unprocessed."}],"issue":"Africa holds key minerals for solar PV, such as copper, tin and silicon, but most countries on their own lack the finance, technological capabilities and infrastructure to build a competitive PV manufacturing sector. China dominates nearly every segment of the global chain.","evidence":"Analysing critical minerals, trade and investment flows, the paper finds only limited and scattered opportunities for local solar PV manufacturing within individual African countries. Diversifying into the global chain is hard given market concentration, high entry barriers and established players. The paper concludes that a regional strategy is the realistic route in.","pdf":"https://afripoli.org/view-pdf/26/solar-photovoltaic-manufacturing-in-africa-opportunity-or-mirage","sources":["https://afripoli.org/solar-photovoltaic-manufacturing-in-africa-opportunity-or-mirage","https://www.pv-magazine.com/2024/10/10/africa-needs-regional-strategy-for-pv-manufacturing/","https://www.greenbuildingafrica.co.za/regionalised-solar-pv-manufacturing-strategy-required-to-integrate-into-the-global-solar-value-chain/"],"notes":""}$rita$::jsonb, 'published'),
('events', 'launch-rita-and-the-policy-insights-series', $rita${"title":"Launch: RITA and the Policy Insights series","eventType":"Launch","format":"online","durationMinutes":60,"language":"English","speakers":["gideon-ndubuisi","elvis-korku-avenyo"],"speakersTbc":["Moderator"],"about":"Meet the team, hear what RITA will work on first, and put your questions to the programme leads.","registrationOpen":true}$rita$::jsonb, 'published'),
('insights', 'no-1-rethinking-africas-green-mineral-future', $rita${"number":1,"title":"Rethinking Africa’s green mineral future","programme":"MIN","series":"Green mineral future","year":2026,"authors":["gideon-ndubuisi"],"topics":["Minerals"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_policy-insights-n1-2026-rethinking-activity-7419682882312388610-cWfB","body":"The evidence is clear: China has emerged as Africa’s mineral processing hub.\n\nTwo figures in our report (https://lnkd.in/eJUPe8hF) are particularly striking and underscore the scale and depth of this transformation.\n\n- China’s consolidation as Africa’s mineral processing hub is not merely a trade outcome but a structural feature of the global green and digital economy.\n- Left unaddressed, this pattern risks locking African economies into a role as suppliers of unprocessed ores while value addition, technological learning, and industrial rents accrue elsewhere.\n\nThe policy imperative is therefore not to decouple from China, but to recalibrate partnerships, incentives, and industrial policies to ensure that mineral extraction translates into domestic processing capacity, industrial capabilities, and long-term structural transformation within Africa.","date":"2026-01-21"}$rita$::jsonb, 'published'),
('insights', 'no-10-blind-spot-its-not-just-about-capital-its-about-how-you', $rita${"number":10,"title":"Blind spot: it’s not just about capital, it’s about how you structure it","programme":"IND","series":"Blind spots","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy","Finance"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_greenindustrialisation-africa-climatefinance-activity-7422869396097851392-OoJX","body":"When discussions turn to financing Africa’s green industrialization, they too often end with a familiar refrain: more capital.\n\nYet in practice, the binding constraint is rarely how much finance is available—it is how that finance is structured.\n\nMany green energy and industrial projects fail not because they lack ambition or technical viability, but because they are built on the wrong financial architecture.\n\nToo often, they rely on:\n\n- Short-term, high-cost capital to finance long-lived industrial projects\n- Unmanaged foreign exchange exposure\n- Climate finance instruments poorly aligned with the realities of industrial development\n\nWithout an appropriate financial structure, even well-designed green power and industrial projects risk becoming stranded assets.\n\nWhat Africa needs, therefore, is not simply more capital, but patient, locally aligned, and purposefully designed blended finance that:\n\n- Matches the long time horizons of industrial transformation\n- Mitigates foreign exchange, demand, and market risks\n- Actively supports domestic manufacturing and the creation of industrial demand\n\nIn short, financing green industrialization is not just about availability—it is about design.\n\nThe real question, then, is not whether Africa can access capital, but whether it can structure finance in ways that transform energy systems and industrial production simultaneously.\n\nElvis K. Avenyo (Ph.D.) Emmanuel Buadi Mensah Woubet Kassa, PhD Solomon Owusu Victor Osei Kwadwo, Ph.D.","date":"2026-01-30"}$rita$::jsonb, 'published'),
('insights', 'no-11-africas-green-industrialization-blind-spot-mind-the-skills', $rita${"number":11,"title":"Africa’s green industrialization blind spot: mind the skills","programme":"INN","series":"Blind spots","year":2026,"authors":["gideon-ndubuisi"],"topics":[],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_africa-greenindustrialization-skillsgap-activity-7423258873043607552-JlcB","body":"Africa’s green industrialization debate is full of ambition—more renewables, more factories, more minerals.\n\nBut there’s a quieter constraining factor: skills. Green tech manufacturing does not scale without skills.\n\nSolar panels, batteries, grids, green hydrogen plants—none of these runs on policy alone. They require:\n\n- Engineers and technicians who can design, install, and operate systems\n- Maintenance and grid management skills to keep infrastructure reliable\n- Applied R&D and learning-by-doing to adapt technologies to local conditions\n\nCapability base does not emerge automatically.\n\n- History is clear: Countries that achieved successful industrialization invested early in human capital development and built strong research institutions and technical education systems.\n\nWeak skills ecosystems in many African economies is a major challenge.\n\n- Too often, projects are built faster than skills systems can absorb them, leading to reliance on imported expertise, high downtime, and limited local spillovers and industrial learning.\n\nSuccessful green industrialization treats skills as infrastructure, not an afterthought. This means:\n\n- Embedding training and apprenticeships into every major energy and industrial project\n- Linking TVET institutions and universities directly to firms and value chains\n- Using public support to finance learning curves, not just hardware\n\nAfrica’s green industrialization will not be constrained by ambition or resources alone.\n\n- A significant constraining factor is whether countries invest seriously in people, capabilities, and learning systems.\n\nThe green industrialization is not only about megawatts—it’s about mastery.\n\nSolomon Owusu Elvis K. Avenyo (Ph.D.) Christian Urom, PhDWoubet Kassa, PhD Victor Osei Kwadwo, Ph.D. Davina Osei Woubet Kassa, PhD","date":"2026-01-31"}$rita$::jsonb, 'published'),
('insights', 'no-12-rethinking-africas-green-mineral-future-foreign-direct', $rita${"number":12,"title":"Rethinking Africa’s green mineral future: foreign direct investment or foreign direct constraints","programme":"MIN","series":"Green mineral future","year":2026,"authors":["gideon-ndubuisi"],"topics":["Minerals"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_greenindustrialization-greenmineral-africa-activity-7423632262543364096-eTaM","body":"Africa has so far missed the transformative potential of foreign direct investment (FDI) inflows into its resource sector.\n\nIn fact, the prevailing model of FDI has not helped to overcome the resource curse; in many cases, it has actively reproduced it.\n\nIt is no longer news that Africa is richly endowed with mineral resources capable of unlocking much-needed industrialization. Yet most foreign investment continues to bypass the industries that could fundamentally transform African economies.\n\nThe result is a persistent pattern: FDI flows overwhelmingly into extraction—mining raw materials—while processing, manufacturing, and local value addition remain largely neglected as can be observed in the figure.\n\nThe resulting challenge is somewhat related to my earlier argument about financing Africa’s industrialization (see Policy Insights N10 [https://lnkd.in/eyZB2mZE] and N8 [https://lnkd.in/erhsq37n]).\n\n- Africa’s real capital challenge is not simply about access or scale, as is often framed in academic and policy debates; it is more of Africa’s inability to attract the right kind of capital.\n- Investment structures that prioritize short-term returns from extraction are poorly aligned with the long-term financing needs and structure for a green mineral-led industrialization in Africa.\n\nAfrica can no longer rely on old investment models. It must think and do things differently: blend public, private, and development finance, design instruments that reward real and genuine local impact and build partnerships that go beyond extraction toward industrial transformation.\n\nThe question, therefore, is not whether Africa can attract capital—it is whether it can structure that capital to deliver transformation.\n\nThe ability of Africa’s green minerals to power its future industrial base, generate jobs, and support sustainable green growth ultimately depends on it.\n\nElvis K. Avenyo (Ph.D.) Solomon Owusu Woubet Kassa, PhD Emmanuel Buadi Mensah","date":"2026-02-01"}$rita$::jsonb, 'published'),
('insights', 'no-13-africas-green-industrialization-blind-spot-politics', $rita${"number":13,"title":"Africa’s green industrialization blind spot: politics","programme":"IND","series":"Blind spots","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_africa-greenindustrialization-greenminerals-activity-7423972208814854144-fFAc","body":"Africa’s green industrialization debate is often technical: megawatts installed, minerals extracted, grids expanded, factories built. But green industrialization don’t entirely fail because of spreadsheets. They often fail because of politics.\n\nGreen industrialization is not a neutral upgrade of technologies. It reshapes power, reallocates rents, and disrupts livelihoods.\n\nThis raises uncomfortable questions that policy documents often sidestep: Who gains? Who loses? Who resists?\n\nWhen these questions are ignored, the outcomes are predictable:\n\n- Pushback from incumbents whose rents are threatened\n- Social resistance to infrastructure that excludes or displaces communities\n- Policy reversals when costs become politically visible and benefits remain abstract\n\nThis is not a design flaw. It is a political economy reality.\n\nSuccessful green industrialization strategies anticipate these questions rather than deny it. Hence they:\n\n- Build credible transition pathways for affected workers and firms\n- Share benefits through local content, community ownership, and jobs\n- Sequence reforms to maintain political coalitions, not just technical efficiency\n\nGreen industrialization is not just about cleaner energy and low carbon technologies; it is about restructuring economies and redistributing opportunities.\n\nIf Africa wants its green industrialization to endure, it must be politically sustainable, not only environmentally sound.\n\nThe hardest part of green industrialization is not building turbines or grids. It is building consensus, compensation, and credibility.\n\nElvis K. Avenyo (Ph.D.) Solomon Owusu Woubet Kassa, PhD Emmanuel Buadi Mensah Victor Osei Kwadwo, Ph.D. Hubert Nii-Aponsah, PhD Davina Osei","date":"2026-02-02"}$rita$::jsonb, 'published'),
('insights', 'no-14-africas-green-industrialization-blind-spot-coordination', $rita${"number":14,"title":"Africa’s green industrialization blind spot: coordination","programme":"IND","series":"Blind spots","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_africa-greenindustrialization-greenminerals-activity-7424334586580574209-sL9I","body":"Africa does not lack green resources. It does not lack ambition.\n\nWhat most African countries lack is coordination capacity.\n\nGreen industrialization is not a single-ministry project. It breaks down when:\n\n- Energy plans are designed without industrial demand\n- Mining policy stops at extraction and ignores processing and value addition\n- Trade policy undercuts domestic green producers\n- Regulators optimise for compliance, not competitiveness\n\nWhen ministries act in silos, green industrialization becomes fragmented—technically sound on paper, economically fragile in practice.\n\nFactories do not run on “efficient markets” alone. They simultaneously need long-term power contracts, predictable pricing, and reliable grids, among others.\n\n- This emerges only where states can coordinate policy, institutions, and incentives over time.\n- Green industrialization is, thus, as much an institutional challenge as it is a technological one.\n\nAfrican countries that will emerge as green industrialized states will not be those with the most solar, hydropower or wind potential—but those that can align energy, mining, industry, and trade policy; empower regulators with developmental mandates; and coordinate across borders.\n\nAfrica's green industrialization challenge isn't just skills [https://lnkd.in/ezHDdR-Y], demand [https://lnkd.in/esCpsRkC], capital structure [https://lnkd.in/eyZB2mZE] or politics [https://lnkd.in/eEtMdiWX]. It’s institutional: a deficit of governance muscle.\n\nElvis K. Avenyo (Ph.D.) Hubert Nii-Aponsah, PhD Rex Asiama (PhD) Solomon Owusu Victor Osei Kwadwo, Ph.D. Rose Camille Vincent, Ph.D. Davina Osei Woubet Kassa, PhD Emmanuel Buadi Mensah","date":"2026-02-03"}$rita$::jsonb, 'published'),
('insights', 'no-15-africas-green-mineral-future-the-real-mineral-processing', $rita${"number":15,"title":"Africa’s green mineral future: the real mineral processing challenge","programme":"MIN","series":"Green mineral future","year":2026,"authors":["gideon-ndubuisi"],"topics":["Minerals"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_africa-mineralprocessing-greenindustrialization-activity-7424696967789912064-EQX3","body":"Much of the policy and academic debate assumes that mineral processing is not happening in Africa.\n\nThat assumption is not entirely true.\n\nMineral processing is taking place across the continent as our recent report (https://lnkd.in/eyQZNxwP) clearly shows).\n\nThe real challenge is not whether Africa processes minerals, but the scale, scope, and variety of that processing.\n\nEvidence from examining export data is sobering:\n\n- The range of processed mineral exports does not reflect Africa’s vast and diverse mineral endowment\n- Processed mineral exports are highly concentrated in a few countries such as the DRC, Morocco, South Africa, and Zambia\n- Processing remains technologically shallow, with most products requiring further refining abroad before use in high-tech industries. Hence, much of the economic value is realized outside the continent\n\nTo be blunt, Africa’s mineral processing profile is heavily tilted toward raw and semi-processed exports.\n\n- The scope of processing is narrow\n- The scale is nowhere near what is needed to drive national, regional, or continental structural transformation\n- The variety of processed minerals falls far short of Africa’s resource potential\n\nThe uncomfortable truth? Africa’s mineral wealth is not translating into industrial power—not because it fails to process minerals, but because it fails to process them seriously.\n\n- Processing without depth, scale, and technological ambition changes very little. It is just not transformative!\n- This also matters for countries that impose export bans on unprocessed minerals. Too often, firms respond by doing the bare minimum processing needed to circumvent regulations—without building meaningful local capabilities.\n\nThe takeaway:\n\n- Africa has the resources. Now it must expand capabilities to ensure mineral processing moves beyond isolated pockets and evolves into a continent-wide, technologically sophisticated ecosystem.\n- The evidence of mineral processing across the continent challenges the dominant narrative—and convenient excuse—that Africa lacks pre-existing capability. While upskilling and further capability building remain essential, the data clearly shows that Africa is not starting from scratch.\n- The problem is not absence. It is insufficient scale, weak depth, and limited strategic intent.\n\nIf mineral processing is going to matter, it must stop being symbolic—and start being strategic.\n\nA regionally led strategy, rather than a purely country-by-country approach, offers a more credible pathway forward.\n\nSolomon Owusu Elvis K. Avenyo (Ph.D.) Woubet Kassa, PhD","date":"2026-02-04"}$rita$::jsonb, 'published'),
('insights', 'no-16-africas-green-mineral-future-when-competition-becomes-self', $rita${"number":16,"title":"Africa’s green mineral future: when competition becomes self-sabotage","programme":"MIN","series":"Green mineral future","year":2026,"authors":["gideon-ndubuisi"],"topics":["Minerals"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_africa-greenminerals-greenindustrialization-activity-7425059358767644672-Wvdc","body":"Global demand for Africa’s green minerals is accelerating and suddenly, Africa is “strategic.” However, this has translated neither into stronger African bargaining power nor meaningful structural transformation.\n\nWhy? Because too often, African countries negotiate alone.\n\nIn fragmented negotiations, power asymmetries dominate. Individual countries—desperate for investment, foreign exchange, or quick wins—offer generous fiscal terms, regulatory concessions, and unrestricted mineral access just to stay “competitive.” But in doing so, they weaken their own leverage and that of their neighbors.\n\nThis matters because bargaining power in mineral markets does not come from possession alone—it comes from scale, coordination, and credible alternatives. Our recent report (https://lnkd.in/eyQZNxwP) shows that most green mineral-endowed African countries lack these essential parameters, necessitating a regional coordinated strategy, rather than a purely country-by-country approach, to win in the green mineral race.\n\nWhen African countries ignore this and act independently:\n\n- Buyers play them off against each other\n- Processing and manufacturing commitments are postponed or diluted\n- Technology transfer becomes optional, not mandatory\n- Industrial learning and capability building are sacrificed for speed\n\nUltimately, what looks like competition is, in reality, a race to the bottom. This is not how green mineral–led industrialization works.\n\nFragmentation weakens leverage, raises costs, and ultimately locks Africa into the familiar role of raw material supplier—just in greener clothes.\n\nAfrica’s real opportunity lies not in undercutting neighbors, but in bargaining and building together. This means:\n\n- Coordinated regional mineral and industrial strategies\n- Shared processing and manufacturing hubs across borders\n- Aligned standards, incentives, and trade rules under the AfCFTA\n- Collective bargaining with global partners around value addition, not just access\n\nActing together, African countries can shift from price takers to value makers—and from fragmented suppliers to indispensable players in the global green economy.\n\nThe green mineral-led industrialization race will not be won by countries competing against each other for the same investors, offering ever-weaker terms. It will be won by those that coordinate, scale, and bargain as one.\n\nThe question is no longer whether Africa has the minerals. It is whether Africa has the political and institutional capacity to stop competing with itself—and start negotiating its future collectively.\n\nSolomon Owusu Elvis K. Avenyo (Ph.D.) Woubet Kassa, PhD","date":"2026-02-05"}$rita$::jsonb, 'published'),
('insights', 'no-17-africas-green-industrialization-reality-check-skills-follow', $rita${"number":17,"title":"Africa’s green industrialization reality check: skills follow demand","programme":"INN","year":2026,"authors":["gideon-ndubuisi"],"topics":[],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_africa-greenindustrialization-afcfta-activity-7425433287419961344-C1we","body":"We often blame Africa’s limited green industrialization on skill shortages. But that’s only part of the story.\n\nIncreasingly, the continent is not short of training programs. What it is short of is demand that sticks.\n\nSkills—engineers, technicians, grid managers, maintenance crews, applied R&D—do not appear in a vacuum. They emerge when firms have orders to fill, contracts to honor, and markets to serve.\n\nConder these scenarios.\n\nScenario 1: Train First, Hope Later\n\n- Africa trains engineers, technicians, and renewable-energy graduates—often at scale. However, demand is fragmented, projects are sporadic and manufacturing orders are thin or uncertain.\n- The result: Skills migrate or shift sectors, firms underinvest in upgrading, and local R&D floats above production\n\n**Implication:** Africa ends up exporting skills and minerals, while importing finished green technologies.\n\nScenario 2: Projects Without Industrial Anchors\n\n- Solar parks, wind farms, and pilot hydrogen projects multiply but each is negotiated in isolation. There is no aggregated demand, no industrial anchor.\n- The result: Limited learning-by-doing, weak local supply chains, and firms have no reason build long-term training pipelines\n\n**Implication:** Green industrialization looks active and busy but the industrial base stays shallow.\n\nScenario 3: Demand-Led Green Industrialization\n\n- Governments do the hard work, coordinating energy, mining, industry, and trade policy. Demand is made visible and credible.\n- The result: Offtake agreements give firms confidence to invest in skills; Anchor buyers (fertilizer, steel, cement, agro-processing) absorb green power and inputs at scale; Public procurement creates early markets for local production\n\nHere, skills emerge because markets exist.\n\nScenario 3 is the only path where Africa stops being just a site of extraction and installation and becomes a site of production, learning, and upgrading.\n\nThe lesson is simple, but uncomfortable: Skills do not lead demand. Demand pulls skills into existence\n\nThe real question is no longer whether Africa have the technology or skills?” It is whether it has the coordinated markets—national and regional—that allow skills to take root?”\n\nThis is the real industrial test of the green industrialization in Africa.\n\nGreen industrialization happens when markets, skills, and production grow together. This is where the AfCFTA becomes quintessential for Africa’s green industrialization.\n\nElvis K. Avenyo (Ph.D.) Victor Osei Kwadwo, Ph.D.Solomon Owusu Woubet Kassa, PhD Rex Asiama (PhD)","date":"2026-02-06"}$rita$::jsonb, 'published'),
('insights', 'no-18-africas-green-industrial-future-afcfta-as-passive-trade-or', $rita${"number":18,"title":"Africa’s green industrial future: AfCFTA as passive trade or active transformer?","programme":"IND","series":"Green industrial future","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_afcfta-greenindustrialization-greenminerals-activity-7425807545182724096-MFA-","body":"Africa's green industrial future faces a unique challenge: abundant potential but fragmented markets. Without scale, firms hesitate to invest, skills remain underdeveloped, and industrial capabilities stall.\n\nThe African Continental Free Trade Area (AfCFTA) is often presented as the magic wand that addresses this challenge. By creating continental markets, it can give firms the confidence to invest, enable learning at scale, and allow skills to take root beyond national borders.\n\nBut here’s the reality check: AfCFTA doesn’t automatically create demand.\n\nUnder AfCFTA, demand emerges only when African states act deliberately and collectively:\n\n- Coordinated public procurement across borders—turning fragmented national orders into continent-scale markets that firms can plan around.\n- Regional anchor buyers—from fertilizer producers to steel and cement plants, agro-processing hubs, and transport systems—committing to long-term offtake that justifies investments in skills, machinery, and R&D.\n- Harmonized regulations and standards—from grid codes to certification rules and industrial regulations—so firms can produce once and sell across the continent, rather than redesigning for every border.\n\nWithout these actions, AfCFTA risks doing only what Africa already does too well: facilitating trade in what is already produced elsewhere. In that scenario, AfCFTA becomes a trade facilitation agreement, not an industrial one.\n\nThe strategic choice is thus clear:\n\n- Passive AfCFTA: Scale fragmentation and competition among African producers. Imports flow easily, skills stagnate, industrial capabilities remain weak.\n- Active AfCFTA: Aggregate African demand to build African industries, develop skills, strengthen R&D, and create resilient, homegrown supply chains.\n\nAmid fragmented markets that plague the continent, how African states use AfCFTA will shape how green industrialization emerges on the continent: thriving industries or just smoother pathways for imports.\n\n**Bottom line:** AfCFTA can either be a passive trade framework or an active industrial instrument. The choice will shape Africa’s green industrialization for decades to come.\n\nElvis K. Avenyo (Ph.D.) Solomon Owusu Emmanuel Buadi Mensah Woubet Kassa, PhD Hubert Nii-Aponsah, PhD Rex Asiama (PhD)","date":"2026-02-07"}$rita$::jsonb, 'published'),
('insights', 'no-19-africas-green-industrial-future-regional-demand-as-the', $rita${"number":19,"title":"Africa’s green industrial future: regional demand as the missing puzzle","programme":"IND","series":"Green industrial future","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_afcfta-greenindustrialization-greenminerals-activity-7426164625890770944-5ihF","body":"We talk a lot about skills, finance, and technology in Africa’s green industrialization.\n\nBut green industrialization doesn’t move on abstractions. It moves when demand is organized at scale.\n\nAmid Africa's fragmented market, this is why regional demand is not a nice-to-have—it is the lifeline of Africa’s green industrial future.\n\nSo what does regional demand actually look like in practice?\n\n- Fertilizer corridors, where multiple countries commit to long-term offtake of green ammonia and green urea—giving firms the confidence to invest in local production and skills.\n- Green steel for African infrastructure, where roads, rail, ports, and housing projects pool procurement across borders—turning construction pipelines into industrial anchors.\n- Electric mobility for public transport, where cities aggregate orders for electric buses and fleets—supporting regional assembly, maintenance, and charging ecosystems.\n- Regional battery value chains, where standardized specifications and pooled procurement create markets for battery assembly, recycling, and systems integration.\n\nThis is what demand looks like when it is bankable, predictable, and continental.\n\nThe lesson is simple but often ignored: Regional demand is not theoretical. It is planned, coordinated, and procured.\n\nThis is where the AfCFTA becomes decisive—not as a trade agreement, but as a demand-aggregating industrial instrument.\n\nWhen demand is organized at scale, firms invest.\n\nWhen firms invest, technology transfer occurs and skills emerge. Ultimately, markets, skills, and production grow together.\n\nWhen this happens, green industrialization becomes real.\n\nThe real question is no longer whether Africa has the resources or the talent. It is whether Africa is willing to organize demand at scale.\n\nThis is the true test of Africa’s green industrialization.\n\nElvis K. Avenyo (Ph.D.) Solomon OwusuEmmanuel Buadi Mensah Woubet Kassa, PhD Hubert Nii-Aponsah, PhD Rex Asiama (PhD)","date":"2026-02-08"}$rita$::jsonb, 'published'),
('insights', 'no-2-calibrating-africas-green-industrialization-strategy-part-1', $rita${"number":2,"title":"Calibrating Africa’s green industrialization strategy, Part 1","programme":"IND","series":"Calibrating","part":1,"of":2,"year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_policy-insights-n1-2026-calibrating-activity-7419995065630035968-Ae1c","body":"Africa’s green industrialization strategy must be calibrated to reflect the hard realities of today’s geoeconomic landscape.\n\nDespite the continent’s abundant endowment of transition minerals, these resources have not translated into commensurate gains in domestic processing, manufacturing, or technological capability—as we demonstrate in our recent report (https://lnkd.in/eJUPe8hF). Instead, value capture has increasingly occurred outside the continent, most notably in China.\n\nThis moment therefore calls for a decisive recalibration of Africa’s green industrialization agenda. Again, the priority is not disengagement from dominant external partners, but strategic leverage—using Africa’s mineral endowments to negotiate technology transfer, co-investment, and regionally anchored processing hubs that support long-term structural transformation. Without such a shift, Africa risks underwriting the global green transition while remaining industrially peripheral to it.\n\nRecalibrating this strategy requires moving beyond aspirational ideals toward policy conditions that are not only essential for repositioning Africa within the emerging green industrial order but also aligned with the region’s current realities. Among others, this includes:\n\n- From partners to terms of engagement: Strategic engagement with external partners must move beyond partnership rhetoric toward enforceable terms. Clear value-addition benchmarks, co-investment in processing infrastructure, and credible technology transfer provisions should define access to Africa’s strategic minerals, not open-ended extraction rights.\n- Industrial policy coherence: Building green industrial ecosystems requires disciplined coordination across ministries, development finance institutions, and regulators. Fragmented policy approaches will continue to undermine Africa’s ability to convert mineral endowments into industrial capabilities.\n- Energy first, slogans later: Green industrialization without reliable, affordable, and scalable energy systems is a contradiction. Power sector reform, grid expansion, and industrial energy planning must precede—or at least move in lockstep with—ambitions for mineral processing and green manufacturing.\n- Capability before complexity: Africa does not need to capture entire green value chains overnight. Strategic sequencing—starting with feasible processing stages and advancing through learning-by-doing—offers a more realistic, resilient, and politically sustainable pathway to industrial upgrading.\n- Regionalize or remain marginal: The capital intensity and scale requirements of green industries exceed the capacity of most individual African economies. African countries must think regionally. A national strategic vision,\n\nembedded and anchored in regional integration, is key.\n\nElvis K. Avenyo (Ph.D.) Solomon Owusu Woubet Kassa, PhD","date":"2026-01-22"}$rita$::jsonb, 'published'),
('insights', 'no-20-africas-green-industrial-future-processing-is-not-enough', $rita${"number":20,"title":"Africa’s green industrial future: processing is not enough","programme":"MIN","series":"Green industrial future","year":2026,"authors":["gideon-ndubuisi"],"topics":["Minerals"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_afcfta-greenindustrialization-greenminerals-activity-7426508911568015360--2Fv","body":"To truly gain from green industrialization, green mineral–endowed African countries must think beyond extraction—and beyond processing.\n\nToo often, African countries are offered a narrow role in the green transition: extract here, process a little, export the rest.\n\nThat path creates activity—but not industrial power.\n\nReal industrial power lies in building end-to-end value chains. We have seen this clearly with China: the strategic focus was not just on moving up the mineral value chain, but on building capabilities in the technologies that depend on those minerals as critical inputs.\n\nEnd-to-end value chains entails functional upgrading along the mineral value chain and mastering production, manufacturing, servicing, and eventually innovation in downstream technologies.\n\nBeyond building industrial power, this is also how countries future-proof themselves.\n\nTechnology substitution is real.\n\nResources are not fixed—they become.\n\nThis means the window of opportunity offered by today’s green minerals is not infinite. Countries that remain stuck at extraction or basic processing risk being left behind as technologies evolve.\n\nEnd-to-end value chains place countries on a steep learning curve because firms, workers, and institutions are continuously exposed to production challenges across extraction, processing, manufacturing, deployment, and maintenance, forcing rapid skill accumulation, technological adaptation, and productivity gains that cannot emerge from isolated activities.\n\nWay Forward\n\n- End-to-end value chains require demand at scale, something that no single African country can generate alone.\n- This is why regional demand under the AfCFTA is decisive. It allows firms to invest across the full value chain.\n\nGreen industrialization will not be won at the mine or the processing plant alone.\n\n- It will be won where markets, skills, and production connect across the entire value chain.\n\nThe real question for Africa’s green industrial future is not: “Can Africa process more?”\n\n- The real question is: “Can Africa build and sustain complete green value chains at scale?”\n- This is how Africa moves from participation to value capture in the green economy.\n\nElvis K. Avenyo (Ph.D.) Solomon Owusu Woubet Kassa, PhD Emmanuel Buadi Mensah Hubert Nii-Aponsah, PhD Victor Osei Kwadwo, Ph.D. Godsway K Tetteh, Ph.D","date":"2026-02-09"}$rita$::jsonb, 'published'),
('insights', 'no-21-technology-lock-in-and-substitution-risk-africas-hidden', $rita${"number":21,"title":"Technology lock-in and substitution risk: Africa’s hidden green industrialization threat","programme":"MIN","year":2026,"authors":["gideon-ndubuisi"],"topics":["Minerals"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_afcfta-greenindustrialization-greenminerals-activity-7426871307226710016-XV3Q","body":"Africa is blessed with critical minerals for the green transition—cobalt, lithium, nickel, rare earths etc.\n\nBut here’s a hard truth: the biggest risk for resource-rich countries is not running out of minerals—it’s running out of relevance.\n\nWhy? Because technologies evolve—and they evolve fast.\n\n- Today’s mineral may underpin tomorrow’s battery technology.\n- But new chemistries, substitutes, or recycling breakthroughs can shift demand away from raw extraction.\n- Countries stuck at extraction or basic processing are price-takers, vulnerable to global shifts.\n\nResources are not inherently valuable—they become valuable depending on what you do with them. Shukuru Amos pens a nice exposé on this (see https://lnkd.in/eFwGRx3H)\n\nThis is where end-to-end value chains are critical.\n\n- Countries that move up the value chain—from extraction to processing, manufacturing, assembly, and even recycling—capture value at each stage.\n- They build skills, know-how, and industrial capability that can adapt as technology shifts.\n- They are not just exporting minerals—they are producing the technologies of the future.\n\nTake batteries as an example:\n\n- A country supplying lithium ore benefits only while demand for raw lithium is high.\n- A country that produces battery-grade chemicals, assembles cells, and integrates storage systems locks in relevance across technological generations.\n\nThe message is clear:\n\n- African countries cannot afford to think linearly—extract → export.\n- They must think holistically—resources → value chains → capabilities → adaptation.\n\nTiming matters. The window of opportunity is finite.\n\n- Countries that fail to move quickly risk watching their minerals become obsolete in global markets while others capture the profits, skills, and industrial learning.\n\nAfrica’s green industrialization is therefore not just about minerals—it’s about strategic foresight, coordination, and industrial ambition.\n\nThe policy challenge is simple but urgent:\n\n- Build end-to-end value chains, not just extraction or basic processing.\n- Coordinate regional demand through mechanisms like AfCFTA.\n- Invest in skills and technology learning that anticipate the next generation of green technologies.\n\nIn the green economy, relevance is more valuable than raw resources.\n\nElvis K. Avenyo (Ph.D.) Solomon Owusu Woubet Kassa, PhD Rex Asiama (PhD) Hubert Nii-Aponsah, PhD Emmanuel Buadi Mensah Victor Osei Kwadwo, Ph.D.","date":"2026-02-10"}$rita$::jsonb, 'published'),
('insights', 'no-22-africas-green-industrialization-the-private-sector-holds', $rita${"number":22,"title":"Africa’s green industrialization: the private sector holds the key, Part 1","programme":"IND","series":"Private sector","part":1,"of":2,"year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_greenindustrialization-greenminerals-criticalminerals-activity-7427233681968369664-9iV0","body":"Africa’s green industrialization will not be delivered by strategies, roadmaps, or declarations alone.\n\nStates can set visions. But without firms investing, producing, learning, and competing, “green industrialization” remains a policy aspiration—not an economic transformation.\n\nThis is the hard part of green industrialization, and it’s the part we often lose focus on when talking about Africa’s green industrial future.\n\nThe private sector is not just a participant; it is the arena where green industrialization either materializes or collapses.\n\nLook at it this way: green industrialization requires firms that are willing to:\n\n- Experiment with processing and manufacturing under uncertainty\n- Absorb, adapt, and localize complex technologies\n- Organize logistics, maintenance, and quality control at scale\n- Meet demanding global standards on cost, carbon, and reliability\n\nThese capabilities are not built by policy documents. They are built by firms that invest, learn, fail, adjust, and try again.\n\nThe implication is clear: without strong domestic and regional private firms willing to take these risks, Africa’s green industrial future will remain narrow and vulnerable—supplying raw inputs while others capture the value, knowledge, and jobs.\n\nWhat then is the way forward:\n\n- De-risk private-sector investment: Green industrialization is capital-intensive, technologically uncertain, and often uncompetitive in its early years. African governments and DFIs must focus on targeted de-risking through concessional finance, co-investment, demand guarantees, and first-loss instruments tied to production and upgrading/innovation.\n- Anchor investments in real demand: Firms invest when markets exist. Without predictable demand, green factories do not scale—no matter how generous the incentives. African governments thus need to aggregate regional markets through AfCFTA, secure public procurement, and establish long-term offtake agreements.\n- Support industrial ecosystems: Successful green industrialization depends on ecosystems. African policymakers should identify and support anchor firms—domestic or regional—that can pull in suppliers, service providers, logistics, and skills. The goal is not a few flagship plants, but dense value chains that generate positive spillovers and externalities.\n\nAfrica’s true green industrial future will be decided on factory floors, in mines, and across industrial ecosystems—where private firms invest, learn, fail, adapt, and scale.\n\nUltimately, the real question is whether policymakers on the continent are ready to shift focus and empower the private sector, or continue with the status quo.","date":"2026-02-11"}$rita$::jsonb, 'published'),
('insights', 'no-23-recalibrating-africas-green-hydrogen-strategy-part-1', $rita${"number":23,"title":"Recalibrating Africa’s green hydrogen strategy, Part 1","programme":"EN","series":"Green hydrogen","part":1,"of":5,"year":2026,"authors":["gideon-ndubuisi"],"topics":["Green hydrogen"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_greenindustrialization-industrialpolicy-afcfta-activity-7427596078671368192-XITO","body":"Many African countries—from Namibia and South Africa to Mauritania, Egypt, and Morocco—are endowed with abundant solar and wind resources.\n\nWhile this gives the continent a natural comparative advantage in green hydrogen production, the real question is: what will Africa do with it?\n\nTwo strategic choices emerge.\n\nOption 1: Export hydrogen molecules.\n\nOption 2: Use hydrogen domestically to produce green steel, fertilizers, chemicals, and synthetic fuels.\n\nThe choice between these two options is not a technical debate. It is a development decision.\n\nIf hydrogen is treated purely as an export commodity (as is currently mostly the case), Africa risks repeating a familiar pattern—exporting raw molecules while importing higher-value industrial products.\n\n- The result? Limited domestic linkages, modest employment effects, and vulnerability to price volatility.\n\nHowever, if hydrogen is embedded into domestic value chains, the story changes. In this case, it uses green hydrogen to produce:\n\n- Green steel that can revive and modernize Africa’s metals industries.\n- Green fertilizers that can strengthen agro-industrial systems and reduce import dependency.\n- Green chemicals and synthetic fuels that can anchor new manufacturing clusters.\n- Low-carbon industrial inputs that can position African producers competitively in a carbon-constrained global market.\n\nThis second option captures more value-added, deepens industrial capabilities, and generates significantly more employment both directly and through backward and forward linkages. Importantly, it aligns with the region's long agenda of achieving structural transformation\n\nHydrogen, therefore, should not be seen merely as an energy export. It is an industrialization platform.\n\nThe strategic question for policymakers is not simply how to attract hydrogen investment—but how to design hydrogen ecosystems that:\n\n- Aligns energy planning with industrial policy\n- Builds domestic demand in steel, fertilizers, and chemicals\n- Uses regional markets (AfCFTA) to scale production\n- Ensures infrastructure is designed around value chains, not just export terminals\n\nAfrica’s green hydrogen moment will only become transformative if it supports structural transformation—not just decarbonization elsewhere.\n\n- Hydrogen can either be another chapter in the resource-export story,\n\nor the foundation of a new green industrial era.\n\nThe choice is strategic.\n\nSolomon Owusu Elvis K. Avenyo (Ph.D.) Woubet Kassa, PhD Hubert Nii-Aponsah, PhD Emmanuel Buadi Mensah","date":"2026-02-12"}$rita$::jsonb, 'published'),
('insights', 'no-24-recalibrating-africas-green-hydrogen-strategy-part-2', $rita${"number":24,"title":"Recalibrating Africa’s green hydrogen strategy, Part 2","programme":"EN","series":"Green hydrogen","part":2,"of":5,"year":2026,"authors":["gideon-ndubuisi"],"topics":["Green hydrogen"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_greenindustrialization-industrialpolicy-afcfta-activity-7427958458215198720-P2NU","body":"Africa’s green hydrogen debate is often framed as a binary choice: Export hydrogen or use it domestically to drive industrialization.\n\nBut what if we do both? What if the real answer is sequencing? In this case, a hybrid model becomes the strategic path for Africa wherein an export-led strategy plays a critical role in the short term.\n\nLook at it this way.\n\nLarge-scale hydrogen projects are capital-intensive. Investors often need long-term offtake agreements, predictable demand, and revenue visibility.\n\n- Given the high-risk, capital-constrained environment of most African countries, export-led hydrogen projects are thus often the only projects capable of mobilizing large-scale finance.\n- However, these projects have the potential to de-risk early investments, anchor infrastructure financing, build operational experience and create demonstration effects that attract follow-on capital.\n\nHypothesis 1: Exports can be a political and financial entry point, not a strategic failure. For many African countries, this is the fastest way to move from strategy documents to bankable projects.\n\nThe real risk lies elsewhere. Notably, when export projects are developed without explicit domestic linkages, Africa risks repeating an old pattern: supplying low-value green inputs while industrial value, learning, and technological capabilities accumulate elsewhere.\n\nHypothesis 2: The issue, therefore, is not export-first—but export-first without a bridge (i.e., export-only strategies). Export-led should not mean export-locked.\n\nA hydrogen strategy that works for Africa lies in treating export as a sequencing tool.\n\n- Phase 1: Leverage export markets to crowd in capital, build renewable capacity, develop infrastructure, and technical skills that outlive individual export contracts\n- Phase 2: Gradually integrate hydrogen into domestic value chains—green fertilizers, green steel, chemicals, refining, synthetic fuels.\n- Phase 3: Use regional markets under AfCFTA to scale hydrogen-based industries beyond national demand constraints.\n\nThis hybrid approach does 3 important things:\n\n- It avoids the trap of waiting for perfect domestic industrial conditions before launching projects.\n- It prevents hydrogen from becoming a permanent enclave export.\n- It aligns green transition strategy with structural transformation.\n\n**Bottom line:** Africa does not need to choose between exporting hydrogen and industrializing. The real choice is whether exports are used to anchor industrialization—or to postpone it.\n\nThe key to a meaningful Africa’s green hydrogen future is governance design where:\n\n- Export contracts can include downstream investment commitments.\n- Local supplier development programs can be embedded early.\n- Skills development can anticipate domestic industrial integration.","date":"2026-02-13"}$rita$::jsonb, 'published'),
('insights', 'no-25-recalibrating-africas-green-hydrogen-strategy-part-3', $rita${"number":25,"title":"Recalibrating Africa’s green hydrogen strategy, Part 3","programme":"EN","series":"Green hydrogen","part":3,"of":5,"year":2026,"authors":["gideon-ndubuisi"],"topics":["Green hydrogen"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_greenhydrogen-greenindustrialization-industrialpolicy-activity-7429045524604870656-CO7T","body":"Hydrogen (H2) roadmaps are emerging across African countries, most of them led by energy ministries, climate agencies, and investment promotion units. The emphasis is typically on production capacity, export terminals, and offtake agreements.\n\nThis pattern raises an uncomfortable question: what if African countries are designing H2 policy as if it were LNG 2.0?\n\nThe answer is familiar:\n\n- Large-scale projects move fast. Export terminals are built. Foreign buyers sign long-term contracts. H2 molecules leave African ports.\n- 10-15 years from now, Africa becomes most likely a competitive exporter of green molecules. GDP rises modestly. Government revenues increase.\n- However, industrial structures will remain largely unchanged. Electrolyzers are imported. Engineering services are foreign-led. Steel and fertilizer industries remain underdeveloped.\n\nResult: high investment, with little or no structural transformation. Africa’s H2 moment MUST BECOME MUCH MORE THAN THIS.\n\nBreaking free from the supposedly “Export enclave path” requires coordinated governance—an argument I have highlighted more broadly in an earlier policy insight (https://lnkd.in/eR7i6VqN).\n\nIn H2 context, this requires energy ministries to design H2 supply but in lockstep where:\n\n- Ministries of Industry shape downstream strategies: green steel, fertilizers, chemicals, synthetic fuels.\n- Ministries of Trade integrate H2-based products into export competitiveness strategies and AfCFTA frameworks.\n- Ministries of Agriculture link green ammonia production to fertilizer security and agro-industrial clusters.\n- Finance ministries and development banks must design instruments that support industrial parks, supplier development, and technology upgrading — not just production facilities..\n\nThe implication of this “coordinated industrial path” is clear:\n\n- Export contracts are negotiated, but include downstream investment commitments.\n- H2 zones are co-located with industrial clusters.\n- Skill systems are aligned early and local firms are integrated into fabrication, maintenance, storage, and component manufacturing.\n\nH2 is not simply a molecule or an export project. It is a potential anchor for industrial ecosystem. What determines whether it fulfills this purpose is “GOVERNANCE”.\n\nWithout deliberate coordination, H2 risks becoming an export commodity. With coordination, it becomes a structural transformation lever.\n\nAfrica’s H2 can therefore become another export corridor or a platform for green industrialization. The choice is institutional, and the window is open now.\n\nElvis K. Avenyo (Ph.D.) Solomon Owusu Woubet Kassa, PhD Emmanuel Buadi Mensah Hubert Nii-Aponsah, PhD Victor Osei Kwadwo, Ph.D.","date":"2026-02-16"}$rita$::jsonb, 'published'),
('insights', 'no-26-recalibrating-africas-green-hydrogen-strategy-part-4', $rita${"number":26,"title":"Recalibrating Africa’s green hydrogen strategy, Part 4","programme":"EN","series":"Green hydrogen","part":4,"of":5,"year":2026,"authors":["gideon-ndubuisi"],"topics":["Green hydrogen"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_greenindustrialization-africa-greenhydrogen-activity-7429795130506727424-pk-M","body":"Most conversations about Africa’s green hydrogen (H2) future start (and end) with the same question: Where can Africa produce H2 cheapest? This question is predominantly guided by an \"export-only hydrogen economy\" logic.\n\nIn earlier policy insights, I’ve argued that Africa’s H2 opportunity is bigger than this. Those insights focused largely on how African countries can expand value capture by integrating H2 into downstream activities to produce green products like green fertilizers and green steel.\n\nBut the H2 economy is not only about molecules and downstream products. It is also about machines like electrolyzers, fuel cell membranes and catalysts, precision-engineered storage tanks, and power electronics\n\nSo, the more strategic question becomes: Can African countries enter the manufacturing value chain of H2 technologies themselves?\n\nWhy does this matter?\n\n- H2 technologies are high-value, knowledge-intensive industries and the global value chains are still forming, creating a window for technology-based industrialization.\n- Technology production confers geopolitical leverage, while reducing technological dependence that may even adversely affect an export-only or domestic-industrial integration H2 model. It also generates positive externalities like skilled jobs, innovation ecosystems and emergence of adjacent sectors.\n\nA technology-based H2 economy model in Africa is not unrealistic. What it requires is strategy.\n\n- H2 demand projections (domestic + export) can be leveraged to justify localized assembly and gradual manufacturing of electrolyzers. Early-stage assembly can evolve into component manufacturing over time.\n- Countries with metal fabrication industries can diversify into precision-engineered storage tanks and pressure vessels. Chemical and materials research institutions can focus on membranes and catalysts.\n- Africa holds PGM critical for certain electrolyzer and fuel cell technologies. This can be leveraged.\n- Governments can align public procurement and industrial policy, where support for H2 projects include local manufacturing and supplier development thresholds tied to capability upgrading.\n\nIntegrating into H2 technology value chains is about positioning\n\n- If Africa only produces H2 using imported technology, it captures energy rents. If it integrates the resource into downstream segments, it gains industrial value. In both cases, however, it is vulnerable to geopolitics\n- But if Africa participates in manufacturing the technologies that power H2 systems, it gains all—plus geopolitical leverage.\n\nThis is the difference between being a supplier or technology dependent in the H2 economy and being a power within it.\n\nAfrica’s H2 strategy should therefore be built on 3 pillars: Energy production. Industrial integration. Technology participation.","date":"2026-02-18"}$rita$::jsonb, 'published'),
('insights', 'no-27-recalibrating-africas-green-hydrogen-strategy-part-5', $rita${"number":27,"title":"Recalibrating Africa’s green hydrogen strategy, Part 5","programme":"EN","series":"Green hydrogen","part":5,"of":5,"year":2026,"authors":["gideon-ndubuisi"],"topics":["Green hydrogen"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_greenindustrialization-africa-industrialpolicy-activity-7430499899940540417-G7II","body":"Green hydrogen (H₂) is increasingly framed as Africa’s next industrial frontier.\n\nIn Policy Insights N26-2026, I argued that Africa's greatest H₂-led industrial opportunity is not just exporting H₂ molecules or derivatives; it lies in embedding African countries into the manufacturing value chain of H₂ technologies.\n\nWhile exciting, the short to medium term goal shouldn't be to localize the entire H₂ tech stack at once. That instinct is understandable. It is also strategically dangerous.\n\nThe H₂ value chain is an ecosystem of highly different technological segments, each with its own barriers to entry.\n\nFrontier areas like electrolysers, advanced membranes, catalysts, and power electronics are capital-intensive, IP-heavy, and dominated by firms with decades of R&D and consolidated supply chains.\n\n- Entering these segments immediately is neither realistic nor necessary. They require cumulative technological capabilities, long research cycles, and large domestic markets to amortize risk.\n- History shows what happens if otherwise: announcement-driven industrialization that struggles to materialize.\n\nHypothesis 1: African countries are more likely to miss out in a H₂ tech value chain not because they move too slowly; but because they try to do everything at once.\n\nThe H₂ tech value chain contains multiple segments that are far more accessible in early industrialization stages:\n\nBalance-of-plant components\n\nStorage systems and tanks\n\nSteel structures and mounting systems\n\nPipes, valves, and fittings\n\nCompression and transport infrastructure\n\nAssembly, installation, operations, and maintenance\n\nThese segments may not headline investment brochures but they are industrially powerful.\n\n- They generate skilled jobs, learning-by-doing, supplier development, and industrial spillovers—without requiring frontier R&D from day one.\n- They build on capabilities many African economies already have: fabrication, welding, engineering, mechanical assembly, and industrial services.\n\nHypothesis 2: A selective, capability-aligned entry strategy anchored in what African countries can realistically produce today and upgrade tomorrow builds credibility with investors and partners, while creating a platform for deeper manufacturing over time.\n\n**Bottom line:** Africa doesn’t need to manufacture everything in the H₂ tech value chain.\n\nSuccessful late industrializers rarely began at the technological frontier. They entered where capability gaps were manageable, built domestic supplier networks, accumulated tacit knowledge through learning-by-doing, and only later moved upstream.\n\nSelective entry in H₂ tech value chain is therefore not a concession. It is a sequencing strategy.\n\nThe question is not whether Africa can manufacture H₂ technologies; it is which parts, when, and under what industrial logic.","date":"2026-02-20"}$rita$::jsonb, 'published'),
('insights', 'no-28-africas-green-industrialization-the-private-sector-holds', $rita${"number":28,"title":"Africa’s green industrialization: the private sector holds the key, Part 2","programme":"IND","series":"Private sector","part":2,"of":2,"year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_greenindustrialization-africa-privatesector-activity-7431648163205255168--HvH","body":"Africa’s green industrialization will not be financed by ambition. It will be financed by bankable projects, largely led by the private sector.\n\nWhy? Governments can set direction. Development partners can provide support. But it is private firms that mobilize capital, deploy technology, build factories, hire workers, and take commercial risks.\n\nAcross the continent, private investors are already showing interest in:\n\nRenewable energy generation and storage\n\nGreen manufacturing and low-carbon materials\n\nBattery assembly and mineral processing\n\nGreen hydrogen production\n\nElectric mobility ecosystems\n\nSustainable agro-processing\n\nThe appetite exists. The momentum is high. But are these enough?\n\nPast experiences across the continent indicate that industrialization strategies that failed to crowd in private capital rarely scaled. At best, they produced isolated projects, not ecosystems. Pilot plants, not industries.\n\nWithout sustained private investment, Africa’s quest for green industrialization may follow similar pattern.\n\nSo, what needs to change?\n\nPrivate firms are not development agencies. They are profit maximizers operating under risk constraints. If the risk-return equation does not work, capital will flow elsewhere.\n\nIf Africa wants to be serious about the role of private firms vis-à-vis private capital, therefore, five things must become standard practice\n\n- De-risk first movers through blended finance structures that absorb early-stage technology and market risks.\n- Provide long-term policy certainty, not shifting annual frameworks.\n- Create demand anchors at domestic and regional levels to reduce market risk.\n- Lower FX and sovereign risk using targeted guarantee and hedging instruments.\n- Align development finance institutions with industrial strategy, not just isolated project lending.\n\n**Bottom line:** Africa’s green industrialization will rise or fall because of private capital. The conversation must therefore move from “Why isn’t private capital coming?” to “What specific financial and policy instruments would make green industrial projects bankable?”\n\nGreen industrialization is not blocked by lack of private capital globally. It is blocked by lack of structured, investable pipelines.\n\nPrivate firms will mobilize capital into renewable energy, battery assembly, green hydrogen, and green manufacturing but only when risk-return profiles align with reality.\n\nThe opportunity of green industrialization in Africa is enormous. The real question is: Is Africa building the financial and institutional architecture to unlock it?","date":"2026-02-23"}$rita$::jsonb, 'published'),
('insights', 'no-29-green-projects-will-not-transform-african-economies-value', $rita${"number":29,"title":"Green projects will not transform African economies. Value chains will","programme":"IND","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_greenindustrialization-greenindustrialpolicy-activity-7432316023720017920-X__k","pullQuote":"Green projects will not transform African economies. Value chains will.","body":"Africa does not need more isolated green projects. If the continent is to leverage the green transition to achieve its long-awaited industrialization, it must build integrated green value chains (IGVCs).\n\nAcross the continent, billions are flowing into utility-scale solar, wind farms, battery minerals, green hydrogen and EV assembly\n\nYet in many cases, the structure looks familiar. Raw minerals exported. Finished products imported. Minimal domestic integration. Foreign firms dominate local engineering, procurement and construction. Local firms confined to low-value tasks.\n\nThis is not green industrialization. It is green extraction in variegated forms.\n\nIsolated green projects deliver megawatts, improve energy access, attract FDI and create temporary construction jobs. But IGVCs develop supplier ecosystems, enable firm upgrading, build technical capabilities, generate domestic value added and create cumulative industrial learning.\n\nLook at it this way. A solar farm that imports everything creates electricity. However, a solar ecosystem that develops local suppliers, logistics firms, service providers, recyclers, and component manufacturers creates industry.\n\nSimply put, one delivers power; the other reshapes economic structure.\n\nIGVCs are one of the missing links in Africa’s green industrialization. Without them, projects remain enclave-like. And enclave models do not transform economies. They create islands of activity in oceans of informality.\n\nSeveral structural constraints explain and reinforce enclave dynamics on the continent: Weak domestic supplier networks. Fragmented regional markets. Infrastructure gaps. High cost of capital. Policy uncertainty. Procurement systems focused solely on lowest import cost\n\nPrivate firms respond rationally to risk. In thin ecosystems, therefore, importing as in the Solar case is safer than sourcing locally.\n\nBut this creates a self-reinforcing equilibrium: No ecosystem → no local sourcing → no ecosystem.\n\nSo what needs to change?\n\nGreen industrial policy in Africa must move beyond project approval toward ecosystem construction by:\n\n- Tying procurement to phased local supplier development\n- Supporting technological upgrading of domestic firms\n- Developing industrial clusters around renewable zones\n- Aggregating regional demand to justify component manufacturing\n- Aligning skills systems with specific green industries\n- Deploying blended finance to de-risk domestic manufacturing\n\n**Bottom line:** Africa's green industrial future lies on the extent to which it leverages green industrial policy to drive and deliver on the strategies listed above, among others.\n\nGreen projects are necessary. IGVCs are transformative. The distinction is not semantic. It is structural.","date":"2026-02-25"}$rita$::jsonb, 'published'),
('insights', 'no-3-calibrating-africas-green-industrialization-strategy-part-2', $rita${"number":3,"title":"Calibrating Africa’s green industrialization strategy, Part 2","programme":"IND","series":"Calibrating","part":2,"of":2,"year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_africagreenindustrialization-regionalintegration-activity-7420357280375750656-4dd9","body":"Africa remains largely on the periphery of the global green economy. Yet a few countries—most notably South Africa, Morocco, and Tunisia—are beginning to emerge as the continent’s green innovation and manufacturing hubs, as illustrated in the figure. While encouraging, this early momentum remains fragmented, uncoordinated, and insufficient to shift Africa’s overall position in global green economy.\n\n- The reality is stark: no single African country possesses the full set of technological, financial, infrastructural, and institutional capabilities required to compete globally in complex green technology value chains. African nations are archetypes of what economists call late industrializers, and their historical challenges in pursuing industrialization are well documented. Layered onto these are the geopolitical complexities of green industrialization, which further heighten the hurdles.\n\nYet there is a viable path forward: regionalized industrial strategy. By coordinating across borders, African countries can collectively create green manufacturing ecosystems that initially serve local and regional markets, while building capabilities that, over the medium to long term, enable African firms to compete meaningfully in global green technology value chains.\n\nThe critical question, then, is: how can Africa integrate its scattered opportunities—its green minerals, untapped energy potential, skills, and nascent green innovation hubs—into a cohesive, continentwide strategy that elevates its role from periphery to gatekeeper in the global green economy?\n\nConsider the possibilities: cobalt mined in the Democratic Republic of Congo could be processed in Zambia, components manufactured in South Africa could be assembled into batteries or EVs in Morocco, creating an interconnected, continentwide value chain. Such integration would transform Africa’s scattered assets into a strategic, competitive green industrial ecosystem.\n\n- The strategy is clear: regionalization is the way forward. However, Africa must move decisively to the next stage—designing and implementing regional green technology production networks that are functional, coordinated, and capable of positioning the continent as an active and competitive player in the global green economy.\n\nElvis K. Avenyo (Ph.D.) Solomon Owusu Woubet Kassa, PhD","date":"2026-01-23"}$rita$::jsonb, 'published'),
('insights', 'no-30-building-africas-green-industry-from-the-ground-up', $rita${"number":30,"title":"Building Africa’s green industry from the ground up","programme":"IND","series":"Ground-up industrialisation","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy","Ground-up industrialisation"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_greenindustrialization-informalsector-africa-activity-7434119056422674432-d0F1","body":"Walk through many African cities and you will see something powerful—and often underestimated:\n\nInformal recyclers sorting plastics and metals\n\nRepair technicians extending the life of appliances and electronics\n\nSolar micro-distributors bringing clean energy to peri-urban communities\n\nCircular economy entrepreneurs turning waste into value\n\nAt the SME level, the private sector is quietly enabling:\n\nMaterial recovery\n\nProduct life extension\n\nClean energy access\n\nResource efficiency\n\nCircular innovation\n\nThese activities are not marginal. They show that Africa’s green transition is already in motion. Yet most of these activities operate:\n\nInformally\n\nWith low productivity\n\nWithout scale\n\nWithout affordable finance\n\nOutside formal industrial policy frameworks\n\nAny meaningful national green industrialization policy or strategy across the continent cannot afford to ignore these segments.\n\nThe real strategic question is not how to replace them, but how we can upgrade them. Why? Replacing them risks deepening unemployment and inequality.\n\nUpgrading them, however, can drive the much-needed green industrialization on the continent.\n\nSo, what does upgrading these activities/segments mean in practice?\n\n- Clear and gradual formalization pathways — not punitive enforcement\n- Access to working capital and asset finance to scale up and facilitate risk sharing\n- Cluster-based infrastructure (shared equipment, testing facilities, warehousing)\n- Public procurement quotas for certified SMEs\n- Technology upgrading and equipment support\n- Skills development tied to market access\n- Certification mechanisms that open doors to larger contracts\n- Integration into larger anchor firms’ supply chains\n- Digital platforms to improve market access and traceability\n\nAfrica’s green industrial future will not be built only in large industrial parks or mega-projects. It will also be built in workshops, repair hubs, waste aggregation centers, and small-scale assembly units.\n\n**Bottom line:** If African countries ignore this layer, they deepen economic dualism: A modern green enclave on one side. A stagnant informal economy on the other.\n\nBut if they integrate and upgrade SMEs, they create dense industrial ecosystems. And dense ecosystems—not isolated projects—are what transform economies.\n\nThe difference between these futures and what Africa ends up with is policy design.\n\nAfrica’s green transition is already happening at the grassroots. The real question is whether policy will recognize it—and scale it.\n\nElvis K. Avenyo (Ph.D.) Solomon Owusu Victor Osei Kwadwo, Ph.D.Keyi Tang, Ph.D. Emmanuel Buadi Mensah Woubet Kassa","date":"2026-03-02"}$rita$::jsonb, 'published'),
('insights', 'no-31-urban-mining-africas-hidden-mineral-economy', $rita${"number":31,"title":"Urban mining: Africa’s hidden mineral economy","programme":"MIN","series":"Ground-up industrialisation","year":2026,"authors":["gideon-ndubuisi"],"topics":["Minerals","Ground-up industrialisation"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_policy-insights-n31-2026-urban-mining-activity-7437443808537088000-5CiH","body":"As Africa debates mineral beneficiation, one opportunity remains largely overlooked: urban mining.\n\nAcross cities like Abidjan, Accra, Lagos, and Dar es Salaam, a sophisticated—yet largely invisible—system already exists for recovering valuable materials from discarded electronics. Informal e-waste networks collect, dismantle, repair, and recover metals from phones, computers, cables, and household appliances every single day.\n\nThese workers extract copper, aluminum, and precious metals—materials that are fundamental to modern industrial systems, such as renewable energy, electrical infrastructure, and electronics manufacturing.\n\nAnd Yes. These are the same metals Africa exports from its mines. They are the same materials around which African governments are now designing “beyond extraction” industrial policies aimed at capturing more value domestically.\n\nYet there is a striking contradiction. Most recovered materials still leave the continent as low-value scrap, exported abroad for refining and reprocessing. Meanwhile, the informal workers who recover these materials often remain trapped in precarious livelihoods.\n\nThis is more than a waste-management issue. It is a major industrial policy blind spot.\n\nUrban mining could become a new pillar of Africa’s mineral industrialization strategy, linking circular economy systems, informal employment, and strategic mineral value chains.\n\nAs global demand for recycled materials rises—and as industries seek lower-carbon inputs—the strategic value of recovered metals will only grow.\n\nSo what needs to change?\n\n- Build small-scale refining capacity. Cities that generate large volumes of e-waste should host modular recycling and refining facilities capable of upgrading scrap into industrial-grade metals.\n- Integrate informal collectors into formal value chains. Policy should focus on formalization, training, and safer working conditions rather than displacement.\n- Develop certification systems for recycled minerals. Traceable “recycled African metals” could become attractive inputs for global manufacturers seeking low-carbon and responsibly sourced materials.\n- Link urban mining to broader industrial policy. Recovered metals can feed domestic industries such as electronics repair, electrical manufacturing, renewable energy systems, and battery assembly.\n\nThe reality is this: Africa’s mineral strategies are often framed around what lies beneath the ground. However, a growing share of strategic materials already exists above ground—in cities, landfills, repair markets, and scrap networks.\n\nRecognizing and investing in this reality could transform Africa’s expanding urban waste streams into a new frontier for mineral-based industrialization.\n\n**Bottom line:** The future of Africa’s mineral economy may not only be in its mines. It may also be in its cities.","date":"2026-03-11"}$rita$::jsonb, 'published'),
('insights', 'no-32-fixing-instead-of-throwing-away-africas-overlooked-green', $rita${"number":32,"title":"Fixing instead of throwing away: Africa’s overlooked green industrial advantage","programme":"INN","series":"Ground-up industrialisation","year":2026,"authors":["gideon-ndubuisi"],"topics":["Ground-up industrialisation"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_africa-repaireconomy-greenindustrialization-activity-7437742936886304768-30_T","body":"While many advanced economies are trying to build circular economies through policy frameworks and industrial strategies, Africa has been operating one organically for decades\n\nWalk through many African cities and you will notice something remarkable\n\nPhones are repaired rather than discarded\n\nAppliances are fixed rather than replaced\n\nVehicle components are reused and rebuilt rather than thrown away\n\nThese are not niche activities. They are a core part of everyday economic life in Africa\n\nBut here is the paradox: Africa's repair ecosystems are rarely recognized as part of industrial policy. At best, they are often treated as survivalist activities rather than understood for what they truly are: productive economic infrastructure that supports resource efficiency, employment, and technological learning\n\nThe result: Africa’s large repair ecosystems remain informal, decentralized, and driven by small-scale entrepreneurs\n\nThis needs to change\n\nGreen industrialization is not only about low-carbon energy systems, industrial decarbonization, or manufacturing green technologies. It is also about resource efficiency and circular economic models, of which the repair economy is an essential component\n\nAfrica’s continued neglect of this ecosystem therefore represents a missed bottom-up opportunity for green industrialization\n\nSo what needs to happen? With the right support, repair ecosystems could evolve from fragmented informal markets into organized clusters that support circular manufacturing and industrial upgrading\n\nThree policy shifts are needed to unlock this potential\n\n- Support repair clusters in urban and rural markets. Providing infrastructure, workspace, reliable electricity, and improved logistics would allow technicians and small firms to scale operation and increase productivity.\n- Invest in skills development for repair technicians. Training and certification programs in electronics, diagnostics, and refurbishment technologies would strengthen technical capabilities and create pathways toward assembly activities, remanufacturing, and light manufacturing.\n- Introduce right-to-repair frameworks that guarantee access to spare parts, repair manuals, and diagnostic tools.\n\n**Bottom line:** Africa’s green industrialization does not have to start from scratch—or begin with complex new systems.\n\nSometimes the first step toward green industrialization is very simple: Fixing what already exists. This already exists in repair markets, workshops, and technician networks across many African countries.\n\nThe real opportunity now is to upgrade and integrate this repair ecosystems into broader green industrial transformation agenda.\n\nElvis K. Avenyo (Ph.D.) Woubet Kassa Solomon Owusu Emmanuel Buadi Mensah","date":"2026-03-12"}$rita$::jsonb, 'published'),
('insights', 'no-33-skills-without-learning-africas-green-industrialization', $rita${"number":33,"title":"Skills without learning: Africa’s green industrialization “base” dilemma","programme":"INN","series":"Learning economy","year":2026,"authors":["gideon-ndubuisi"],"topics":["Learning economy"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_greenindustrialization-learningeconomy-skills-activity-7438105323640459264-VdyA","body":"Across Africa, the conversation on green industrialization is saturated with one familiar concern: skills.\n\nWe hear the same message repeatedly—Africa needs more engineers. More technicians. More renewable energy specialists. It is thus unsurprising that across the continent, countries are investing in STEM education and green technology training.\n\nThis focus is understandable. Green industrialization in its full spectrum is technology-intensive, and building a skilled workforce matters. But skills alone do not create industrial transformation.\n\nConsider two possible futures\n\n- In the first, a country trains thousands of graduates in renewable energy and battery technologies. Yet domestic firms lack technological capabilities and production capacity. Solar panels, batteries, and wind turbines are imported.\n\nThe result? The country produces skilled graduates, but the industries that use those skills are located elsewhere. Graduates migrate. Some move into unrelated sectors. Ultimately green transition happens but largely without domestic industrialization.\n\n- Now imagine a different scenario. Education investments are paired with industrial learning strategies. Governments support domestic firms entering renewable energy value chains. Local companies assemble solar components, experiment with battery recycling, and build electric mobility supply chains. Universities collaborate with industry.\n\nThe result? Skills do not sit idle. They are absorbed into a system that learns.\n\nThe latter reflects how industrial transformation historically occurred. From Japan to South Korea, skills expanded alongside industries that were actively learning by doing. Firms built capabilities through production. Workers developed tacit knowledge through experience. Institutions supported experimentation and technological adaptation.\n\nSkills mattered because they were embedded in industrial ecosystems. Africa must follow a similar path if industrialization is the goal.\n\nThe real question is thus not simply: “How do we train more people?” It is: \"What kind of economy will absorb and grow those skills?\"\n\nA learning economy is one where firms, workers, and institutions continuously experiment, adapt, and upgrade capabilities. Learning happens not only in universities, but in factories, workshops, supply chains, and industrial ecosystems.\n\n**Bottom line:** Skills without learning = green transition without industrialization. If Africa wants to leverage green transition to drive real green industrialization, skills must be embedded in learning economies.\n\nAfrica’s green industrial future will not be built only in classrooms. It will be built in economies that learn. This requires shifting from human capital strategies to industrial learning strategies.","date":"2026-03-13"}$rita$::jsonb, 'published'),
('insights', 'no-34-the-learning-economy-a-missing-link-in-africas-green', $rita${"number":34,"title":"The learning economy: a missing link in Africa’s green industrialization","programme":"INN","series":"Learning economy","year":2026,"authors":["gideon-ndubuisi"],"topics":["Learning economy"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_policy-insights-n34-2026-the-learning-activity-7438467706040827904-CFPD","body":"Yes! Green industrialization in its full spectrum is knowledge-intensive, and Africa must expand its technical capabilities to become a key player.\n\nBut there is a deeper lesson from development history that Africa cannot ignore: skills without industrial ecosystems rarely transform economies. Why? industrial ecosystems produce learning economies.\n\nA learning economy is one where firms, workers, and institutions continuously experiment, adapt, and upgrade capabilities. Many African economies lack this, and this is what I call Africa's Green Industrialization \"Base\" Dilemma.\n\nThree structural gaps including skills without industrial demand, weak firm capabilities, and fragmented knowledge systems illustrate this on the context.\n\nSkills without industrial demand: Many African countries are expanding training in renewable energy, electrical engineering, and green technologies. Yet much of the continent’s solar panels, wind turbines, batteries, and grid technologies are imported.\n\nThe result? The continent produces skilled individuals, but the industries that need those skills are located elsewhere.\n\nWeak firm capabilities: Technological learning happens primarily inside firms through production, experimentation, and problem-solving. Yet in many African economies, domestic firms struggle to enter complex manufacturing or technology-intensive sectors.\n\nThe result? Without firms integrating in these value chains, the opportunities for industrial learning that are transformative remain thin.\n\nFragmented knowledge systems: In many African countries, universities, research institutes, governments, and industry operate largely in isolation. Research often remains disconnected from production. Firms rarely collaborate with universities. Policy frameworks are sometimes designed without strong links to industry needs.\n\nThe result? When knowledge systems are fragmented, capabilities do not accumulate and learning does not diffuse across the economy.\n\nAfrica’s green industrial future rests on addressing these structural gaps, among others. So, what needs to happen?\n\n- Align skills strategies with industrial strategies. Train for sectors where domestic production is being built.\n- Strengthen domestic firms through local content policies, supplier development, and strategic procurement that allow firms to learn by producing, enter green value chains and accumulate technological capabilities.\n- Strengthen industry–university ecosystems where research, experimentation, and commercialization reinforce each other.\n- Leverage regional cooperation. Regional industrial ecosystems can create larger markets, deepen supply chains, and accelerate learning across borders.\n\n**Bottom line:** One of the key challenges to Africa’s green industrialization is not simply producing more skilled graduates. It is building LEARNING ECONOMIES.","date":"2026-03-14"}$rita$::jsonb, 'published'),
('insights', 'no-35-africas-green-industrial-future-the-learning-economy-as-a', $rita${"number":35,"title":"Africa’s green industrial future: the “learning economy” as a prerequisite","programme":"INN","series":"Learning economy","year":2026,"authors":["gideon-ndubuisi"],"topics":["Learning economy"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_policy-insights-n35-2026-africas-green-activity-7439193111706165248-NVyQ","body":"Much of the debate on Africa’s green industrialization (GI) focuses on technology, investment, and skills. While these matter, what truly underpins a successful industrialization is a “LEARNING ECONOMY”\n\nA learning economy is one where firms, workers, and institutions continuously experiment, adapt, and upgrade capabilities.\n\nEconomic history shows that industrialization is driven not only by investment or resources, but by how effectively societies generate, apply, and diffuse knowledge over time.\n\nThe industrial rise of economies such as South Korea, Japan, and Taiwan, were as a result of a deliberately created economic system that learned rapidly and continuously. Notably, workers learnt through experience and problem-solving on the shop floor. Firms learnt through production, experimentation, and competition. Institutions learnt through policy experimentation, coordination, and institutional upgrading.\n\nThis continuous interaction between firms, workers, and institutions created a system where knowledge accumulates and spreads across sectors. China is replicating this same model, using it to drive global leadership in several GREEN TECHNOLOGIES.\n\nThis insight is particularly important to Africa’s green industrial future.\n\nGI, in its full spectrum, is evolving at extraordinary speed. Technologies are improving, costs are falling, and production methods are constantly changing. In such a world, static capabilities quickly become obsolete. Countries must thus constantly upgrade.\n\nFor Africa, this means GI cannot be reduced to building renewable infrastructure or exporting critical minerals. It requires building learning systems where firms experiment, workers accumulate practical knowledge, and institutions support continuous upgrading.\n\nAcross successful industrializing economies, 5 learning mechanisms proved particularly powerful:\n\n- Learning-by-doing: Firms and workers build capabilities through production itself.\n- Learning-by-using: Technologies are adapted to local conditions, often generating new innovations.\n- Learning-by-interacting: Firms collaborate with suppliers, universities, and research institutes, accelerating knowledge diffusion.\n- Learning-by-trading: Exposure to global markets through export and/or import pushes firms to upgrade quality, productivity, and technology.\n- Adaptive institutions: Governments constantly adjust policies, refine incentives, and respond to new technological and market realities.\n\n**Bottom line:** For Africa to lead in the GI race, it calls for policy shifts that integrates and localizes these learning mechanisms.\n\nThis is best summarized this way: i) a shift from human capital strategies to industrial learning strategies; and ii) developing adaptive industrial institutions that experiment, learn from policy outcomes, and adjust strategies as technologies and markets change.","date":"2026-03-16"}$rita$::jsonb, 'published'),
('insights', 'no-36-firms-and-knowledge-institutions-charting-africas-green', $rita${"number":36,"title":"Firms and knowledge institutions? Charting Africa’s green industrial learning economy","programme":"INN","series":"Learning economy","year":2026,"authors":["gideon-ndubuisi"],"topics":["Learning economy"],"originalUrl":"https://sites.google.com/view/gideonndubuisi/policy-insights"}$rita$::jsonb, 'published'),
('insights', 'no-37-ground-up-green-industrialization-africas-informal-economy', $rita${"number":37,"title":"Ground-up green industrialization: Africa’s informal economy as a neglected learning ecosystem","programme":"INN","series":"Ground-up industrialisation","year":2026,"authors":["gideon-ndubuisi"],"topics":["Learning economy","Ground-up industrialisation"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_policy-insights-n37-2026-ground-up-activity-7441729202774663169-unml","body":"It is no longer news that Africa’s informal (repair, scrap and recycle) economy holds immense potential for a \"ground-up\" green industrialization. This has been the focus of a few Policy Insights on this platform.\n\nBut what if it offers something deeper? What if Africa’s informal economy is not just a starting point but a fully functioning learning ecosystem that we can LEARN from, LEVERAGE, and SCALE?\n\nJust look closely! In scrap metal markets, plastic recovery networks, e-waste clusters, and repair sectors across African economies, we see continuous, practice-based industrial learning.\n\nWorkers in this ecosystem aren’t waiting for formal training or policy support. They learn by dismantling, repairing, and recovering value from what others discard.\n\nIn Nigeria, for instance, it is uncommon to find a roadside mechanic without formal engineering education diagnosing complex engine faults, improvising tools, and restoring functionality under severe constraints.\n\nThis is not improvisation born out of necessity alone. It is capability formation in action where actors within systems accumulate deep, experience-based knowledge in:\n\n- how to identify and separate valuable materials\n- how to extend the life of products through repair and refurbishment\n- how to adapt tools and techniques to local conditions\n- how to operate efficient, low-cost recovery and recycling processes\n\n**Implication:** Africa’s informal economy is already doing what any successful industrial system must do: learn, adapt, and upgrade continuously.\n\nTwo things make this unique:\n\n- the learning is at its most organic: distributed, practice-based, and deeply embedded in local realities\n- it is also happening in a decentralized, highly resilient manner, mostly without policy support, infrastructure, or formal recognition\n\nAt a time when formal industrial systems in many African countries remain fragmented, this implies that the informal economy may well be the continent’s largest and most functional industrial learning platform.\n\nYet conversations often treat the sector as a problem to be eliminated, rather than a system to be strengthened.\n\nThis is a strategic mistake and calls for a rethink.\n\nIf we take the idea of the informal economy as a learning system seriously, three shifts become urgent: LEARN from it and not just regulate it. LEVERAGE it as a foundation for green capabilities. SCALE it from survival to industrial transformation.\n\n**Bottom line:** Africa’s learning economy, requisite for green industrialization, isn’t starting from zero. It already has one hidden in plain sight. It has millions of people learning, adapting, and innovating every day under conditions that demand efficiency, creativity, and resilience.\n\nThe real question is how the continent can learn, leverage, and scale what it already knows how to do.","date":"2026-03-23"}$rita$::jsonb, 'published'),
('insights', 'no-38-ground-up-green-industrialization-learning-from-leveraging', $rita${"number":38,"title":"Ground-up green industrialization: learning from, leveraging and scaling Africa’s neglected ecosystem","programme":"INN","series":"Ground-up industrialisation","year":2026,"authors":["gideon-ndubuisi"],"topics":["Learning economy","Ground-up industrialisation"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_policy-insights-n38-2026-ground-up-share-7441408200853221376-nekN","body":"When we think of green industrialization in Africa, we often jump straight to high-tech industries. While this is good, the framing creates two problems: it fuels the false narrative that Africa lacks a foundation for green industrialization and blinds us to opportunities hiding in plain sight.\n\nAfrica’s repair, scrap, and recycling ecosystems represent one of such opportunities. They are already performing essential circular economy functions including, recovering value, extending product lifecycles and reducing waste. But even more importantly, they generate knowledge.\n\nInside these ecosystems, workers and micro-enterprises continuously learn by doing. They experiment, adapt, and refine techniques with little or no policy support, infrastructure, or formal recognition.\n\nYet these ecosystems are rarely recognized as part of industrial policy. This is a major industrial policy blind spot.\n\nAfrica’s green industrialization, especially as it concerns circular economy will not emerge only from high-tech plants and imported solutions.\n\nIt will also be built from what already exists. This includes the repair workshop, scrap yard, e-waste cluster and ultimately, the millions of workers who are already learning, adapting, and innovating every day.\n\n**Implication:** Africa’s industrialization challenge isn't necessary a lack of foundation. It is not fully recognizing or leveraging the one it already has.\n\nThis is evident as, too often, policy approaches across the continent aim to formalize or replace informal systems, assuming that progress requires starting over. This limits Africa’s window of opportunity and risks destroying accumulated knowledge instead of building on it.\n\nA more strategic approach requires that these ecosystems become the entry point for Africa’s green industrialization, bridging low-tech recovery activities with higher-value recycling, manufacturing, and green production. Given that they also hold immense “LEARNING” opportunities, amid limited policy support and resource constraints, they are industrial learning platform. This isn't trivial given Africa’s fragmented learning system in the formal sector.\n\nFrom an industrial policy perspective, African policymakers must therefore:\n\n- Learn from this ecosystem on how innovation, skills, and circularity emerge organically under resource constraint and outside formal institutions\n- Leverage this ecosystem as hubs for green skills and entry points into circular value chains\n- Scale this ecosystem through upgrading, integration into formal industrial systems, and enabling growth from micro to small, and from small to industrial scale\n\n**Bottom Line:** Africa’s repair, scrap and recycle ecosystems are not peripheral. They are a ground-up industrial learning platform.\n\nThe task is thus clear: Learn from it. Leverage it. Scale it.","date":"2026-04-05"}$rita$::jsonb, 'published'),
('insights', 'no-39-africas-ev-policy-wave-strategic-leap-or-premature', $rita${"number":39,"title":"Africa’s EV policy wave: strategic leap or premature transition?","programme":"EN","series":"EVs","year":2026,"authors":["gideon-ndubuisi"],"topics":["EVs"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_africa-greenindustrialization-industrialpolicy-share-7448336252036136960-37EJ","body":"An increasing number of African governments are developing electric vehicle (EV) policies, signaling a growing recognition of the global shift toward low-carbon mobility. From Rwanda’s e-mobility incentives to South Africa’s ongoing EV policy discussions, the continent is positioning itself—at least on paper—within the future of transport decarbonization.\n\nBut this raises a critical question: Are African EV policies aligned with structural realities, or are they outpacing them?\n\nAt one level, the push toward EVs reflects legitimate strategic ambition. At another, it exposes a set of deep contradictions that cannot be ignored.\n\n- First, the infrastructure gap remains substantial. Many countries face unreliable electricity supply, limited grid capacity, and low renewable energy penetration. Electrifying transport without addressing these constraints risks shifting emissions rather than reducing them.\n- Second, affordability and market structure present challenges. EVs remain significantly more expensive than internal combustion engine vehicles, and Africa’s vehicle markets are dominated by second-hand imports. Without targeted industrial and fiscal policies that address these concerns, EV adoption may remain limited to elite segments, reinforcing inequality rather than enabling inclusive transitions.\n- Third, there is a risk of policy mimicry. In some cases, EV policies appear to replicate frameworks from Europe or China without sufficient adaptation to local industrial capabilities, urban forms, or mobility needs. This raises concerns about policy coherence and long-term sustainability.\n\nThese, nevertheless, Africa’s evolving EV policies is not a dead end. The real question isn’t whether Africa should pursue EVs but how it should do.\n\nEV policy cannot exist in isolation. It must be embedded within a broader development strategy—one that integrates industrial policy, energy system planning, and the lived realities of African mobility systems.\n\nIf properly sequenced and embedded, Africa’s EV policies could:\n\n- Anchor local industrialization through battery assembly and component manufacturing\n- Strengthen regional integration via harmonized standards and cross-border value chains\n- Unlock leapfrogging pathways, especially in two- and three-wheelers where electrification is already viable\n- Create synergies between transport and renewable energy systems\n\n**Bottom line:** Africa’s EV transition must not be reduced to a decarbonization agenda imported from elsewhere. It must be reimagined as an industrialization strategy.\n\nThis means moving beyond adoption targets toward building productive capabilities, investing in enabling infrastructure, and designing policies that reflect Africa’s structural conditions.\n\nOnly then can EVs move from aspiration to transformation.","date":"2026-04-10"}$rita$::jsonb, 'published'),
('insights', 'no-4-africas-green-mineral-partnerships-opportunity-or-trap', $rita${"number":4,"title":"Africa’s green mineral partnerships: opportunity or trap?","programme":"MIN","series":"Green mineral future","year":2026,"authors":["gideon-ndubuisi"],"topics":["Minerals"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_greenindustrialization-criticalminerals-africa-activity-7420696576215400448-D-nA","body":"African countries are rapidly signing bilateral and multilateral green mineral partnerships with global actors to promote value addition. This surge reflects growing recognition of Africa’s strategic role in the global energy transition.\n\nBut design and governance matter.\n\nThese agreements are largely negotiated at the national level with individual African countries. Yet historical evidence suggests that unilateral mineral agreements with external actors have frequently resulted in extractive outcomes rather than durable development gains on the continent. Moreover, a recent policy report (https://lnkd.in/edc89ZJu) notes that while many of the nascent green mineral agreements include provisions on mineral value-chain integration, joint ventures, investment, knowledge transfer, and capacity building, most are negotiated with limited transparency, rely on vague and non-binding commitments, and have short time horizons.\n\nWhat does this mean for Africa’s green mineral future?\n\n- More agreements do not translate into structural transformation: The predominance of non-binding, time-limited, and opaque provisions in the design of these agreements limit their ability to induce durable investment in domestic processing and manufacturing. Without enforceable commitments and long-term horizons, these partnerships risk reproducing pit-to-port models under a green guise rather than enabling sustained industrial upgrading.\n- Fragmentation kills scale and learning: While most of the green mineral agreements are negotiated at the national level, Africa’s true green industrialization strength lies at the regional level as we argued and showed in our recent report (https://lnkd.in/eJUPe8hF). It is thus safe to argue that Africa’s current approach to these agreements is self-sabotage.\n- Uncertainty discourages long-term industrial investment: Vague commitments, limited transparency, and short validity periods create regulatory and policy uncertainty for both domestic and foreign investors. They discourage investments in smelting, refining, and intermediate manufacturing, activities that require patient capital, stable policy frameworks, and long-term demand certainty.\n\n**Bottom line:** Africa’s green mineral future is not predetermined. Without stronger governance, regional coordination, and binding value-addition commitments, today’s “green partnerships” risk entrenching dependency. With strategic recalibration, they could underpin Africa’s green industrialization.\n\nElvis K. Avenyo (Ph.D.) Solomon Owusu Woubet Kassa, PhD","date":"2026-01-24"}$rita$::jsonb, 'published'),
('insights', 'no-40-africas-green-industrialization-requires-learning-states', $rita${"number":40,"title":"Africa’s green industrialization requires learning states","programme":"IND","series":"Learning economy","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy","Learning economy"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_learningstates-industrialpolicy-africa-activity-7449323661335040000-wwBU","body":"In much of Africa, industrial policies have traditionally been designed as a fixed blueprint: carefully written, formally adopted, and then slowly implemented. This needs to change as the continent calibrates its green industrial strategy, either at the national, regional or continental level.\n\nGreen transition does not behave in predictable ways. Technologies shift. Markets evolve. Global value chains reconfigure. What works today may fail tomorrow.\n\nWinning the green industrial race thus requires learning as fast as the transition itself. This is the LEARNING CHALLENGE. The learning is not just for firms or workers. Institutions must continuously learn, adjust and adapt. Invariably, the STATE itself cannot remain static. It must evolve into a learning state.\n\nThis is why Africa’s green industrial future cannot be governed by rigid policies on papers alone. It requires states that experiment, adapt, and learn in real time.\n\nA learning state does three things differently.\n\n- It treats policy as a hypothesis, not a fixed solution. It pilots. It tests. It accepts that some initiatives will fail—and uses that failure as data.\n- it embeds feedback loops into governance. What are firms struggling with? Where are bottlenecks emerging? What technologies are actually working on the ground? Policy is constantly adjusted based on real-world signals.\n- It aligns public institutions around missions, not silos. Energy, industry, trade, and finance ministries don’t operate in isolation—they co-evolve around shared green transformation goals.\n\nThis is not policy uncertainty—it is structured adaptability. And it matters because the terrain is shifting fast.\n\nThe green transition is inherently uncertain. Whether in renewable energy systems, battery value chains, green hydrogen, or circular economy industries, no country is working with a complete blueprint. Even advanced economies are learning by doing.\n\nFor Africa, this is a strategic advantage waiting to be seized as latecomer countries are not burdened by legacy systems to the same extent. They can leapfrog but only if their states are agile enough to learn, coordinate, and respond decisively.\n\nThis is where the real competition lies.\n\nSo the question isn't who has the best strategy. The real question is: Who can adapt their strategy the fastest?\n\n**Bottom Line:** African economies that will lead the green industrialization aren't those with the largest mineral reserves, biggest markets, or most external financing but that remain policy-rigid.\n\nThey will be those that can learn faster than the pace of change. Attaining this feat requires a LEARNING STATE that can turn uncertainty into capability.","date":"2026-04-13"}$rita$::jsonb, 'published'),
('insights', 'no-41-forget-teslas-africas-ev-boom-is-happening-elsewhere-but-we', $rita${"number":41,"title":"Forget Teslas: Africa’s EV boom is happening elsewhere, but we have a problem","programme":"EN","series":"EVs","year":2026,"authors":["gideon-ndubuisi"],"topics":["EVs"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_electricmobility-africa-energytransition-activity-7450869195325636609-a4iM","body":"We might be thinking about EVs in Africa all wrong.\n\nWhile the global conversation is obsessed with electric cars, the real transformation on the African continent is happening elsewhere.\n\nAnd honestly—that’s where the story gets interesting.\n\nEast Africa is quickly emerging as a serious EV hub on the continent.\n\nCountries like Ethiopia, Kenya, Rwanda, Tanzania, and Uganda are leading the change through policy, pilots, and early adoption (see the figure attached).\n\nBut here’s what stands out most to me. The transition isn’t driven by private cars like in Europe or the US. It’s being driven by motorcycles and 3-wheelers—the true backbone of daily mobility in this region. This is a complete system redesign and that’s why this moment feels bigger than just “EV adoption.”\n\nThis feels like a classic leapfrog moment. Africa has the chance to skip the legacy systems and build something more suited to its reality.\n\nBut here’s a hard truth we can’t ignore: electricity remains a greatest challenge.\n\nMore than 600 million people in Sub-Saharan Africa still lack reliable access to power. Even those with access suffer from unstable power supply. Without solving this, the idea of scaling e-mobility (no matter the vehicle type) hits a ceiling.\n\nCompanies like Roam and Ampersand are building parallel infrastructure models to work around electricity-related constraints, among others. Though impressive and necessary, this raises a critical question: Can fragmented, niche solutions really support a continent-wide transition? It also raises localization challenge.\n\nIf Africa is going to unlock the full potential of e-mobility, it will take more than isolated innovation. It requires national, system-level solutions: integrated power, transport, and policy working together at scale.\n\n**Bottom Line:** If e-mobility is already taking shape on the continent despite its electricity constraints, addressing this challenge will redefine the global EV playbook.\n\nWhy? Africa’s e-mobility transition isn’t about luxury vehicles or early adopters. It is about mass, everyday mobility at scale. So, if it wins here; it wins big.","date":"2026-04-17"}$rita$::jsonb, 'published'),
('insights', 'no-42-industrial-ambition-without-institutional-transformation', $rita${"number":42,"title":"Industrial ambition without institutional transformation: Africa’s industrial policy challenge","programme":"IND","series":"Industrial policy architecture","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_africa-industrialpolicy-statecapability-activity-7459481416280559616-e7T0","body":"It is no longer news that industrial policy is back on the global development agenda.\n\nAfter decades of market fundamentalism, even advanced economies are now openly deploying industrial policy to secure supply chains, accelerate green transitions, and rebuild strategic industries.\n\nAfrica is understandably responding to this moment. But is it on the right path?\n\nAcross the continent, national governments are advancing industrial ambitions tied to green minerals, battery value chains, pharmaceuticals, agro-processing, manufacturing, and renewable energy.\n\n- These efforts are in the right direction. However, there has been little corresponding transformation in the underlying institutional architecture.\n- This reflects a persistent, but erroneous, assumption that industrial policy is automatically developmental.\n\nConsider three possible scenarios.\n\nThe developmental pathway: Industrial policy is tied to clear performance targets, learning incentives, and accountability mechanisms. Firms receiving support are expected to upgrade, innovate, and scale production.\n\n- Under this scenario, industrial policy becomes a vehicle for capability building and structural transformation.\n\nThe distributive pathway: Support is allocated through political proximity rather than productive potential. Subsidies and incentives become instruments of patronage.\n\n- Under this scenario, industrial policy reproduces rent-seeking and protects inefficient incumbents instead of upgrading industries.\n\nThe extractive continuity pathway\n\nIndustrial policy exists on paper, but the economy remains locked into raw commodity exports. Minerals are extracted, value is exported, and domestic production systems fail to deepen.\n\n- Under this scenario, the language of industrialization advances, but the structure of dependency remains intact.\n\n**Implication:** Industrial policy does not produce transformation simply because governments announce incentives, establish industrial parks, or publish strategic plans.\n\nWithout institutions capable of disciplining capital, coordinating investment, monitoring performance, and institutionalizing learning, industrial policy can easily become a mechanism for rent distribution rather than productive transformation.\n\nThis shifts the debate from policy design alone to institutional transformation and state capacity building as the future of Africa’s industrialization will likely be shaped by which of the scenarios described above becomes dominant.\n\n**Bottom Line:** Africa does not merely need industrial ambition. It needs State and institutions capable of converting ambition into production. This is where the continent’s real frontier of industrial transformation lies.\n\nIndustrial policy succeeds not because it exists, but because it is governed well.","date":"2026-05-11"}$rita$::jsonb, 'published'),
('insights', 'no-43-productive-vs-distributive-coalitions-reimagining-africas', $rita${"number":43,"title":"Productive vs distributive coalitions: reimagining Africa’s industrial policy architecture","programme":"IND","series":"Industrial policy architecture","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_policy-insights-n43-2026-productive-share-7461989240181026816--1df","body":"Industrial policy is back. Africa is understandably responding to this moment, as highlighted in the previous Policy Insight (N42-2026). However, their dominant response is guided by similar logic: more infrastructure, more financing, more incentives, more industrial parks, more protection.\n\nBeneath Africa’s current industrial policy activism lies a deeper political economy question that is too often ignored: Are these policies building productive or distributive coalitions?\n\nThis distinction is not semantic. It explains why industrial policy in some contexts drives structural transformation, while in others it merely redistributes rents.\n\nA PRODUCTIVE COALITION is anchored in productive investment, technological upgrading, export competitiveness, capability accumulation, learning, and long-term structural transformation. Here,\n\n- political and economic actors are aligned around expanding productivity and building competitive industries;\n- state support is conditional: firms are expected to perform, upgrade, and compete;\n- protection is temporary and tied to clear discipline—exports, innovation, and domestic value creation.\n\nOutcome: Industrial policy becomes developmental.\n\nA DISTRIBUTIVE COALITION, on the other hand, is organized around rent allocation, patronage networks, political survival, elite accumulation, and short-term bargaining. Here,\n\n- industrial policy shifts from transformation to distribution;\n- subsidies become political rewards. Protection becomes permanent. Local content rules become channels for connected firms;\n- state-owned enterprises become patronage hubs.\n\nOutcome: Industrial policy becomes performative rather than developmental.\n\nDifferences between productive and distributive coalitions explain why having an industrial policy is not enough. Countries can adopt identical industrial policy instruments and still produce radically different outcomes depending on the underlying coalition.\n\n**IMPLICATION:** Industrial policy failure is rarely just technical. It is fundamentally political economy failure.\n\nTHIS IS WHERE AFRICA’S INDUSTRIAL DEBATE MUST MATURE\n\nAfrica cannot remain narrowly focused on: more infrastructure, more financing, more incentives, more industrial parks, and more protection. These are necessary, but insufficient.\n\nIndustrial policy isn't inherently developmental. Without reshaping the incentives and coalitions that govern state–business relations, it risks reinforcing distribution rather than enabling transformation.\n\nThis leads to the real question: Who is Africa's industrial policy ultimately designed to serve—productive transformation or distributive accumulation?\n\n**Bottom line:** Africa’s industrial future will depend less on whether states intervene, and more on whether that intervention is governed by productive or distributive coalitions.","date":"2026-05-18"}$rita$::jsonb, 'published'),
('insights', 'no-44-africas-industrial-window-of-opportunity-why-strategic', $rita${"number":44,"title":"Africa’s industrial window of opportunity: why strategic timing matters","programme":"IND","series":"Industrial policy architecture","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_africa-industrialpolicy-greentransition-share-7477937221250134016-380v","body":"There are moments in global economic history that quietly reshape who produces what, where, and why, and ultimately who captures value.\n\nWe are currently living in one of those moments.\n\nThe global economy is undergoing a profound reconfiguration: the green transition is accelerating demand for critical minerals and low-carbon technologies\n\nSupply chains are being diversified away from concentrated hubs in Asia in pursuit of resilience, security, and geopolitical risk reduction\n\nGeoeconomic competition is reshaping industrial strategy across major powers and industrial policy is no longer an exception — it is becoming the norm\n\nThis global shift creates a rare structural opening for late-industrializing regions.\n\nFor Africa, in particular, the implications of these global structural transition are significant.\n\n- The continent sits at the centre of several emerging value chains, from critical minerals for batteries and renewable energy systems, to land, agro-processing potential, and a growing labour force.\n- In principle, this is a moment of opportunity. But opportunity is not automatic transformation. Even worse, the same forces that create opportunity can also reproduce dependency and structural retrogression.\n- The one million question is thus whether African economies can convert this geopolitical and economic realignment into domestic productive capability.\n\nHistory offers two important lessons.\n\n- First, global windows of opportunity do not automatically translate into industrial transformation.\n- Second, global windows of restructuring do not remain open indefinitely. They quickly harden into new hierarchies.\n\n**Implications:** Africa meaningfully gaining from the ongoing global green transformation will not be determined by its resource endowments. It will be determined by the policy choices and the capabilities the economies within it accummulate. At the same time, these policy choices and capability accumulation are time bound.\n\nThis is where strategic timing becomes decisive. Why?\n\n- Countries that move early, with coherent industrial strategy, capable institutions, and coordinated regional markets, will shape the next phase of global production networks.\n- Those that do not may find themselves locked into familiar roles, even in a “green” global economy.\n\n**Bottom line:** Without a timely strategic action, Africa risks repeating a familiar pattern: exporting raw materials for the green transition, while importing the technologies, machinery, and high-value components that define it.\n\nThe real issue is thus not whether Africa is part of the global shift. It is whether Africa is positioned to shape its terms. That is the challenge of this moment. And it will not wait.","date":"2026-07-01"}$rita$::jsonb, 'published'),
('insights', 'no-45-the-missing-variable-in-africas-industrial-policy-debate', $rita${"number":45,"title":"The missing variable in Africa’s industrial policy debate: political settlements","programme":"IND","series":"Industrial policy architecture","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_policy-insights-n45-2026-the-missing-share-7482313486350516224-SKYx","body":"Across African economies, governments are identifying strategic sectors, setting localization targets, and introducing incentives for critical minerals, and green transition technologies.\n\nThe debate that follows is usually the same: Which industrial policies should governments adopt?\n\nBut this is only part of the story. A more fundamental question is: Who decides which sectors receive support, and why?\n\nIndustrial policy is not simply about correcting market failures. It is about allocating scarce resources, opportunities, and rents. These decisions are rarely technical as I showed in \"Policy Insights N43-2026\" and \"Policy Insights N13-2026\".\n\nIndustrial policies and their outcomes are shaped by political settlements—the distribution of power among political elites, firms, bureaucracies, financiers, and other influential actors.\n\nThis is where the nature of the political settlement becomes decisive. PolicyInsights N43-2026 highlights two contrasting cases:\n\n- A productive political settlement where state support is linked to credible performance obligations. Here, industrial policy is a mechanism for capability accumulation and structural transformation.\n- A distributive political settlement where access to industrial support is determined largely by political proximity, patronage, or coalition maintenance. Here, the language is industrialization, but the outcome is rent distribution.\n- But there is also a third possibility—an extractive political settlement where industrial policy is publicly embraced but never allowed to challenge the underlying economic structure. Here, policy changes at the level of rhetoric, but not at the level of accumulation.\n\nThese varieties means that the same industrial policy can produce very different outcomes.\n\nThis is particularly important in Africa’s current moment and requires asking one more question. Are industrial policies designed to transform the productive structure, or merely to preserve the existing political settlement?\n\n**Implication:** The green transition has created a rare industrial window for Africa.\n\n- But opportunity alone will not deliver transformation. That opportunity will also not be seized simply because governments identify priority sectors.\n- The opportunity will be seized only where political coalitions are organized around production rather than patronage, capability rather than capture, and long-term transformation rather than short-term distribution.\n\n**Bottom line:** Africa's industrial future will depend less on the sectors governments choose than on the coalitions, institutions, and power structures that shape those choices.\n\nThat is the debate we should be having. The challenge thus is not only to design better policies and identify priority sectors. It is to build good political settlements.","date":"2026-07-13"}$rita$::jsonb, 'published'),
('insights', 'no-5-why-africa-must-enter-the-green-industrialization-race-now', $rita${"number":5,"title":"Why Africa must enter the green industrialization race now","programme":"IND","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_greenindustrialization-africa-energytransition-activity-7421068452985049089-EG24","body":"The global green transition is not waiting for Africa.\n\n- As green value chains rapidly consolidate around established processing hubs—especially in China—the window for late entry is narrowing fast. Countries that build processing capacity, set technological standards, and anchor supplier networks today will dominate green industries tomorrow.\n- For Africa, delay carries a real risk: being locked into a long-term role as a supplier of raw or semi-processed minerals, while value, jobs, and technological capabilities are captured elsewhere. Once infrastructure, standards, and industrial ecosystems are entrenched outside the continent, catching up becomes exponentially harder.\n- This is not about abundance of resources—Africa has those. It is about speed, coordination, and capability.\n\nEntering the green industrialization race means:\n\n- Moving beyond extraction to processing and manufacturing\n- Designing regional green industrial strategies, not isolated national bets\n- Aligning energy systems, industrial policy, and finance\n- Using minerals as leverage for technology transfer and capability building\n\nThe green transition will define the next phase of global industrial leadership. Those who hesitate will supply it; those who act will shape it. Borrowing one of Mark Carney's line at Davos: \"If you are not at the table, you are on the menu.”\n\n⏱ Africa still has a choice—but not unlimited time.\n\nOur recent report (https://lnkd.in/eJUPe8hF), relying on a regional developmentalism thinking, surfaces and interrogates key parameters that should inform a regionally coordinated strategy that assures green Industrial development victory for Africa by Africa.\n\nElvis K. Avenyo (Ph.D.) Solomon Owusu Woubet Kassa, PhD","date":"2026-01-25"}$rita$::jsonb, 'published'),
('insights', 'no-6-africas-green-hydrogen-future-are-we-on-the-right-path', $rita${"number":6,"title":"Africa’s green hydrogen future: are we on the right path?","programme":"EN","year":2026,"authors":["gideon-ndubuisi"],"topics":["Green hydrogen"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_africa-greenindustrialization-regionalintegration-activity-7421441734913560576-vTXc","body":"Africa’s Hydrogen Strategy Is Too Export-Focused—and That’s a Problem\n\nAfrica’s green hydrogen debate is dominated by export narratives, shaped largely by external demand from Europe and Asia.\n\nExports matter. But an export-first strategy risks reproducing a familiar pattern: Africa supplying low-value green inputs while industrial value, jobs, and capabilities are created elsewhere.\n\nWhat is missing is a clear focus on domestic demand and industrial integration.\n\n- Green hydrogen can support Africa’s own steel, fertilizer, refining, transport, and power sectors—anchoring demand, accelerating decarbonization, and supporting structural transformation.\n- Equally overlooked are opportunities in hydrogen-related manufacturing. Electrolysers, storage systems, power electronics, pipelines, and balance-of-plant components are where learning-by-doing, jobs, and technological capabilities are built. Yet these segments remain largely absent from discussions of Africa’s hydrogen future.\n\nWithout strong domestic demand, manufacturing linkages, and hydrogen-related manufacturing capabilities;\n\n- Hydrogen risks becoming a new enclave sector: green in color, but extractive in structure.\n- The absence of national or regional hydrogen-related manufacturing capabilities deepens technological dependence. In an era of intensifying geopolitical competition, as seen in ongoing US–China trade tensions, this should be a strategic concern.\n\nA recalibrated approach would position green hydrogen as a dual-use industrial platform: enabling exports where Africa is competitive, while simultaneously building domestic markets and hydrogen-related manufacturing ecosystems.\n\n- This requires aligning hydrogen strategies with industrial policy, public procurement, infrastructure planning, and skills development—rather than treating hydrogen as a narrow foreign-exchange opportunity.\n\nThe real question is not whether Africa can export green hydrogen, but whether it will use hydrogen to industrialize or simply export it to help others do so.\n\nElvis K. Avenyo (Ph.D.) Solomon Owusu Woubet Kassa, PhD Emmanuel Buadi Mensah","date":"2026-01-26"}$rita$::jsonb, 'published'),
('insights', 'no-7-connecting-minerals-to-meals-africas-missed-agricultural', $rita${"number":7,"title":"Connecting minerals to meals: Africa’s missed agricultural link","programme":"MIN","year":2026,"authors":["gideon-ndubuisi"],"topics":["Minerals"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_africa-greenindustrialization-regionalintegration-activity-7421798890628284416-4hXM","body":"The narrative around Africa’s agricultural potential is often framed almost entirely in terms of land. We are frequently reminded that the continent holds about 65% of the world’s uncultivated arable land—roughly 874 million hectares, a landmass larger than Europe and the Americas combined (https://lnkd.in/ewjbnNpf).\n\nBut land alone does not grow food.\n\nWhat is far less discussed is that Africa’s agricultural potential also lies beneath the soil, in its vast endowment of agro-minerals—the phosphates, potash, natural gas, and limestone that underpin modern agricultural productivity. These resources are the foundational inputs for fertilizers, soil conditioning, and sustained yield growth in modern agriculture.\n\nThis disconnect has produced a striking paradox: Africa imports most of the fertilizers it needs while exporting the raw minerals required to produce them. The result is high input costs for farmers, low and volatile productivity, and persistent vulnerability to global supply shocks.\n\nThe future of African agriculture, therefore, is not only about how much land it has—it is also about how strategically it uses the resources beneath it.\n\nSome African countries show what is possible when this disconnect is addressed.\n\n- Morocco, through OCP, has built a globally competitive phosphate-to-fertilizer industry while increasingly tailoring fertilizers to African soil conditions.\n- Nigeria is leveraging its natural gas resources to expand domestic fertilizer production, significantly reducing imports and improving availability for farmers.\n\nTo scale these successes, a shift in priorities is required. Core policy actions include:\n\n- Build local fertilizer and agro-input manufacturing, anchored in Africa’s own mineral resources\n- Link mining, industrial, and agricultural policies, rather than treating them as separate silos\n- Support regionally integrated value chains to achieve scale, reduce costs, and stabilize supply\n- Use public procurement, financing, and regulation strategically to crowd in private investment\n\nUnlocking Africa’s agricultural potential therefore requires a shift in policy focus—from acreage to capabilities and linkages.\n\nAfrica does not lack potential. It lacks coherent, integrated policy action to convert mineral wealth into productive agricultural systems and ultimately, into structural transformation.\n\nElvis K. Avenyo (Ph.D.) Solomon Owusu Woubet Kassa, PhD Emmanuel Buadi Mensah African Development Bank Group African Center for Economic Transformation (ACET)","date":"2026-01-27"}$rita$::jsonb, 'published'),
('insights', 'no-8-waiting-for-solidarity-wont-work-why-africa-must-lead-in', $rita${"number":8,"title":"Waiting for solidarity won’t work: why Africa must lead in financing its own green industrial future","programme":"IND","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy","Finance"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_greenindustrialisation-africa-developmentfinance-activity-7422213483489914880-uhLn","body":"For years, Africa’s green industrial ambitions have been framed around external solidarity such as climate finance pledges, concessional windows, and promises of technology transfer. Yet delivery has been slow, fragmented, and often misaligned with the continent’s industrial priorities. The gap between ambition and financing reality continues to widen.\n\nThe uncomfortable truth is this: there is no automatic solidarity in financing Africa’s green industrialisation. What exists instead are interests, risk assessments, and global capital markets.\n\n- This does not mean Africa should disengage from external finance. It means Africa must shift from waiting to leading.\n\nLeading requires anchoring green industrial finance domestically and regionally. In practical terms, this means:\n\nMobilising domestic and regional capital as the foundation, not the afterthought\n\nDeploying public development banks, pension funds, and sovereign instruments more strategically to absorb risk and crowd in private investment\n\nTreating green industrialisation as an investment and productivity agenda, not a donor-project\n\nLeveraging external finance to complement African priorities, not define them\n\n- History is clear: every successful late industrialiser financed its transformation primarily through domestic effort, political commitment, and institutional innovation, while engaging global capital on its own terms. Green industrialisation will be no different.\n\nThe real question is not whether Africa deserves solidarity—it does. However, is Africa willing to assert agency, take calculated risks, and finance its industrial future with or without it?\n\nElvis K. Avenyo (Ph.D.) Solomon Owusu Woubet Kassa, PhD Emmanuel Buadi Mensah African Center for Economic Transformation (ACET)","date":"2026-01-28"}$rita$::jsonb, 'published'),
('insights', 'no-9-africas-green-industrialization-blind-spot-who-will-buy', $rita${"number":9,"title":"Africa’s green industrialization blind spot: who will buy?","programme":"IND","series":"Blind spots","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://www.linkedin.com/posts/gideon-ndubuisi-phd-0421017b_greenindustrialization-criticalminerals-africa-activity-7422508030656786432-5dkd","body":"Africa’s green industrialization debate is dominated by supply: more renewables, bigger grids, new factories, critical minerals.\n\nBut the toughest question is still missing: who will buy or better still what economists call \"demand\"?\n\nConsider three common scenarios:\n\n- Scenario 1: Clean power without industry -- A country invests heavily in solar and wind. Generation capacity rises but without anchor industrial users, power demand remains weak, tariffs stay high, and clean plants are underutilized.\n- Scenario 2: Green factories without markets -- A battery, fertilizer, or green cement plant is built. Inputs are available and technology is proven. But without long-term offtake agreements, the project struggles to secure finance and operate at scale.\n- Scenario 3: Imports crowd out local production -- Governments talk industrialization, yet public procurement continues to favor cheaper imports. Domestic green producers are left exposed in their most fragile early years.\n\nThese outcomes are not technical failures, they are demand failures.\n\nGreen industrialization will not scale without:\n\n- Long-term industrial offtake agreements that make investments bankable\n- Anchor buyers in fertilizer, steel, cement, agro-processing, and mining\n- Strategic public procurement that creates early markets for green products\n\nCountries that industrialized successfully did not wait for demand to emerge, they created it deliberately.\n\nIf Africa wants clean power and green manufacturing to deliver jobs and competitiveness, demand creation must become a core industrial policy tool, not an afterthought.\n\nThe real question shouldn’t be all about whether Africa can produce green energy and/or manufacture low-carbon technology components. It should also be about whether it can guarantee markets for green industry.\n\nElvis K. Avenyo (Ph.D.) Emmanuel Buadi Mensah Solomon Owusu Woubet Kassa, PhD","date":"2026-01-29"}$rita$::jsonb, 'published'),
('jobs', 'call-for-abstracts-rita-2027', $rita${"title":"Call for abstracts, RITA Conference 2027","jobType":"Call for abstracts","location":"Johannesburg and online","deadline":"31 March 2027","reportsTo":"Conference chairs","summary":"Present your research at the first RITA Conference, 9–10 September 2027. Nine tracks on Africa’s green industrial transformation. Free to submit.","body":"<p>RITA 2027 asks what it takes to industrialise through the green transition: the states, finance, value chains, energy, firms and workers that turn resources into production and jobs.</p><p>Submit a 300–500 word abstract for a paper, poster, organised panel or policy roundtable. Every abstract gets two reviews. Accepted papers are presented with a discussant, and strong full papers are invited to the RITA Working Paper Series.</p><p>Travel support is available on application for Africa-based PhD candidates and early-career researchers.</p>","applyUrl":"/conference/submit"}$rita$::jsonb, 'published'),
('jobs', 'call-for-contributions-policy-insights', $rita${"title":"Call for contributions, Policy Insights","jobType":"Call for contributions","location":"Remote","deadline":"Rolling","summary":"Pitch or submit a Policy Insight: one idea in 600–900 words on Africa’s green industrialisation.","applyUrl":"/submit","reportsTo":"Editor, Policy Insights"}$rita$::jsonb, 'published'),
('opeds', 'africas-mineral-strength-is-wasted-if-countries-dont-work-together', $rita${"title":"Africa’s mineral strength is wasted if countries don’t work together – new report","outlet":"The Conversation","date":"2026-09","authors":["Ndubuisi","Avenyo","Owusu","Kassa"],"kind":"research-blog","programme":"MIN","outletUrl":"https://theconversation.com/africas-mineral-strength-is-wasted-if-countries-dont-work-together-new-report-290306","summary":"Transition minerals are found in 48 African countries, but most still export them raw and capture little value. Drawing on a World Bank–commissioned study, the authors argue that only regional cooperation, shared infrastructure and coordinated policy can turn mineral wealth into regional value chains.","keyPoints":["Most individual countries hold small global shares of each mineral, which weakens their bargaining power alone.","Local refining adds value: Congolese cobalt roughly triples in price after refining.","Pooled trade policy, shared processing centres and partnerships with local processing and skills transfer are proposed."],"sources":["https://theconversation.com/africas-mineral-strength-is-wasted-if-countries-dont-work-together-new-report-290306","https://www.downtoearth.org.in/africa/africas-mineral-strength-is-wasted-if-countries-dont-work-together-new-report"]}$rita$::jsonb, 'published'),
('opeds', 'awakening-industrial-economic-recovery-in-south-africa', $rita${"title":"Awakening industrial economic recovery in South Africa","outlet":"CCRED-IDTT Policy Brief","date":"2021-07","authors":["Avenyo","Bell","Nyamwena","Robb"],"kind":"policy-brief","programme":"IND","outletUrl":"https://www.competition.org.za/s/IDTT4_PB_Awakening_industrial_economic_recovery_in_South_Africa_202107.pdf","summary":"A policy brief from the Industrial Development Think Tank on reviving South Africa’s industrial economy after the COVID-19 shock.","sources":["https://www.competition.org.za/s/IDTT4_PB_Awakening_industrial_economic_recovery_in_South_Africa_202107.pdf","https://www.competition.org.za/idtt-year-4"]}$rita$::jsonb, 'published'),
('opeds', 'beyond-load-shedding-how-south-africas-electricity-crisis-scarred', $rita${"title":"Beyond load shedding: how South Africa’s electricity crisis scarred industry and deepened deindustrialisation","outlet":"African Arguments","date":"2026-10","authors":["Ndubuisi","Avenyo"],"kind":"research-blog","programme":"EN","summary":"Load shedding has ended, but the damage to manufacturing has not. Drawing on two studies in Energy Policy and Energy Economics, the authors show that outages cut jobs, postponed investment and cost export opportunities, and argue that restoring power does not restore lost capabilities.","outletUrl":"https://africanarguments.org/?p=48463","keyPoints":["Firms cut jobs, delayed investment, bought costly backup power and lost export opportunities.","Repeated interruptions broke the continuity manufacturing employment depends on.","Ending load shedding is only the beginning: electricity must be treated as productive infrastructure."],"sources":["https://africanarguments.org/?p=48463"]}$rita$::jsonb, 'published'),
('opeds', 'catastrophic-effects-of-covid-19-health-expenditure-shocks-and-poverty', $rita${"title":"Catastrophic effects of COVID-19 health expenditure shocks and multidimensional poverty in Ghana: what financing mechanisms mattered?","outlet":"AERC Policy Brief AHCV-PB-007","date":"2023-11","authors":["Ayanore","Avenyo","Osei"],"kind":"policy-brief","outletUrl":"https://publication.aercafricalibrary.org/handle/123456789/3696","summary":"More than half of Ghanaian households in the sample spent over 5% of their total expenditure on COVID-19-related health costs. Multidimensional poverty made these catastrophic payments worse, while insurance, remittances and government assistance softened the shock.","keyPoints":["52.2% of households spent more than 5% of total expenditure on COVID-19-related health costs.","Multidimensional poverty exacerbated catastrophic payments during the pandemic.","Insurance, remittances and government assistance mitigated the effects."],"sources":["https://publication.aercafricalibrary.org/handle/123456789/3696"]}$rita$::jsonb, 'published'),
('opeds', 'chinese-investment-in-africa-a-double-edged-sword-for-low-carbon', $rita${"title":"Chinese investment in Africa: a double-edged sword for low-carbon industrialisation","outlet":"BU Global Development Policy Center","date":"2024-07","authors":["Owusu","Tang","Ndubuisi"],"kind":"research-blog","programme":"IND","outletUrl":"https://www.bu.edu/gdp/2024/07/28/chinese-investment-in-africa-a-double-edged-sword-for-low-carbon-industrialization/","summary":"Chinese greenfield manufacturing investment raised industrial carbon emissions in Africa, especially when it went into labour- and resource-intensive manufacturing; the same effect does not appear for OECD investment. The authors argue for reshaping Chinese FDI, not discouraging it.","keyPoints":["Chinese FDI raised industrial emissions in 34 African countries (2003–2014).","The effect is strongest in labour- and resource-intensive manufacturing.","No such increase is found for FDI from OECD countries."],"sources":["https://www.bu.edu/gdp/2024/07/28/chinese-investment-in-africa-a-double-edged-sword-for-low-carbon-industrialization/"]}$rita$::jsonb, 'published'),
('opeds', 'climate-change-mitigation-for-late-industrialisers-technology-intensity', $rita${"title":"Climate change mitigation for late industrialisers: technology intensity in manufacturing","outlet":"SARChI Industrial Development Policy Brief 2023-01 (with CBDS, Copenhagen Business School)","date":"2023-02","authors":["Avenyo","Tregenna"],"kind":"policy-brief","programme":"IND","outletUrl":"https://www.uj.ac.za/wp-content/uploads/2021/10/sarchi-id-pb-2023-01-avenyo-e--tregenna-f--january-2023.pdf","summary":"Late industrialisers need manufacturing to grow, but heavy industrialisation can raise emissions. Drawing on evidence from 56 developing economies, the brief asks whether greener industrial policy, shifting towards higher-technology manufacturing, lets countries industrialise while limiting emissions.","sources":["https://www.uj.ac.za/wp-content/uploads/2021/10/sarchi-id-pb-2023-01-avenyo-e--tregenna-f--january-2023.pdf","https://research-api.cbs.dk/ws/portalfiles/portal/89602649/elvis_korku_avenyo_et_al_climate_change_mitigation_for_late_industrialisers_publishersversion.pdf"]}$rita$::jsonb, 'published'),
('opeds', 'digital-industrialisation-of-freshness', $rita${"title":"Digital industrialisation of freshness","outlet":"CCRED-IDTT Policy Brief 2022/09","date":"2022-09","authors":["Chisoro-Dube","Avenyo"],"kind":"policy-brief","programme":"INN","outletUrl":"https://www.competition.org.za/s/IDTT5-PB9-Digital-Industrilisation-of-freshness_Final_06072022.pdf","summary":"A policy brief on how digital technologies are changing fresh-produce value chains in South Africa, part of the Industrial Development Think Tank’s series on climate change and green industrialisation.","sources":["https://www.competition.org.za/s/IDTT5-PB9-Digital-Industrilisation-of-freshness_Final_06072022.pdf","https://www.competition.org.za/idtt-year-5"]}$rita$::jsonb, 'published'),
('opeds', 'digital-technology-adoption-and-performance-in-south-african', $rita${"title":"Digital technology adoption and performance in South African manufacturing firms: early evidence for policy","outlet":"AERC Policy Brief","date":"2022-03","authors":["Avenyo","Bell"],"kind":"policy-brief","programme":"INN","outletUrl":"https://publication.aercafricalibrary.org/handle/123456789/3404","summary":"South Africa is a technological follower, and the recovery of its manufacturing may depend on faster digital adoption. The brief shows that the effects of new technologies differ across firms and industries, so digital industrial policy must weigh firm-level factors.","sources":["https://publication.aercafricalibrary.org/handle/123456789/3404"]}$rita$::jsonb, 'published'),
('opeds', 'financing-digital-industrialisation-in-south-africa-emerging-issues', $rita${"title":"Financing digital industrialisation in South Africa: emerging issues","outlet":"CCRED-IDTT Policy Brief 2023/5","date":"2023-03","authors":["Nyamwena","Avenyo"],"kind":"policy-brief","programme":"INN","outletUrl":"https://www.competition.org.za/s/IDTT-2022-2023-PB5_Finance-and-digitalisation.pdf","summary":"Survey evidence from South African manufacturers shows that finance matters for the adoption of digital technologies. The brief sets out the emerging issues in financing digital industrialisation.","sources":["https://www.competition.org.za/s/IDTT-2022-2023-PB5_Finance-and-digitalisation.pdf","https://www.competition.org.za/idtt-year-6"]}$rita$::jsonb, 'published'),
('opeds', 'global-value-chains-job-creation-and-job-destruction-among-firms-in', $rita${"title":"Global value chains, job creation and job destruction among firms in South Africa","outlet":"STEG Policy Brief, Growth Research Platform (CEPR)","date":"2026-03","authors":["Ndubuisi","Owusu"],"kind":"policy-brief","programme":"INN","outletUrl":"https://grp.cepr.org/publications/steg-policy-brief/global-value-chains-job-creation-and-job-destruction-among-firms","summary":"Using data on the universe of formal manufacturing firms in South Africa, the brief finds that joining global value chains brings a net job gain. The gain is driven by firms entering GVCs, largely younger and smaller ones; firms that stay in GVCs shed jobs overall.","keyPoints":["GVC integration is linked to net job gains at the firm level.","Continuous GVC participants show an overall net job loss.","Gains are driven mainly by younger and smaller firms."],"sources":["https://grp.cepr.org/publications/steg-policy-brief/global-value-chains-job-creation-and-job-destruction-among-firms","https://steg.cepr.org/sites/default/files/2023-08/WP073%20NdubuisiOwusuGlobalValueChainsJobCreation.pdf"]}$rita$::jsonb, 'published'),
('opeds', 'how-global-value-chains-are-reshaping-jobs-in-south-africa', $rita${"title":"How global value chains are reshaping jobs in South Africa","outlet":"LSE Business Review","date":"2026-09","authors":["Ndubuisi","Owusu"],"kind":"research-blog","programme":"INN","outletUrl":"https://blogs.lse.ac.uk/businessreview/2026/09/30/how-global-value-chains-are-reshaping-jobs-in-south-africa/","summary":"Global value chains both create and destroy jobs in South Africa. Net gains come from new, small and young firms entering GVCs, while long-standing participants shed jobs.","sources":["https://steg.cepr.org/projects/global-value-chains-job-creation-and-job-destruction-among-firms-south-africa"]}$rita$::jsonb, 'published'),
('opeds', 'implications-of-covid-19-on-digital-transformation-in-south-africa', $rita${"title":"Implications of COVID-19 on digital transformation in South Africa","outlet":"CCRED-IDTT Policy Brief 2022/08","date":"2022-07","authors":["Avenyo","Bell","Nyamwena"],"kind":"policy-brief","programme":"INN","outletUrl":"https://www.competition.org.za/s/IDTT5-PB8-Implications-of-COVID-19-on-digital-transformation-in-South-Africa.pdf","summary":"Drawing on a survey of 516 South African manufacturing firms, the brief shows how COVID-19 interacted with the shift to digital technologies. Uneven digital uptake weakens the resilience of the firms and industries most exposed to shocks.","sources":["https://www.competition.org.za/s/IDTT5-PB8-Implications-of-COVID-19-on-digital-transformation-in-South-Africa.pdf","https://www.uj.ac.za/wp-content/uploads/2021/10/sarchi-id-pb-2023-04-avenyo-e-k--bell-j-f--nyamwena-j--march-2023.pdf"]}$rita$::jsonb, 'published'),
('opeds', 'informal-workers-in-senegal-mali-and-burkina-faso-hit-harder-by-covid-19', $rita${"title":"Informal workers in Senegal, Mali and Burkina Faso have been hit harder by COVID-19","outlet":"The Conversation","date":"2021-09","authors":["Balde","Boly","Avenyo"],"kind":"op-ed","programme":"INN","outletUrl":"https://theconversation.com/informal-workers-in-senegal-mali-and-burkina-faso-have-been-hit-harder-by-covid-19-168122","summary":"A survey of 900 people in Senegal, Mali and Burkina Faso in spring 2020 found that informal workers were more likely to lose their jobs, see their earnings fall and struggle to meet basic needs. The authors set out what this means for social protection and support for small businesses.","keyPoints":["Informal workers were more likely to lose their jobs and earnings.","The pattern held in high-risk sectors too.","Informal workers were more likely to struggle to meet basic needs."],"sources":["https://theconversation.com/informal-workers-in-senegal-mali-and-burkina-faso-have-been-hit-harder-by-covid-19-168122","https://unu.edu/article/informal-workers-senegal-mali-and-burkina-faso-have-been-hit-harder-covid-19"]}$rita$::jsonb, 'published'),
('opeds', 'localisation-and-industrialisation-nexus-lessons-for-south-africa', $rita${"title":"Localisation and industrialisation nexus: lessons for South Africa","outlet":"CCRED-IDTT Policy Brief 2023/1","date":"2023-03","authors":["Nyamwena","Avenyo","Bosiu"],"kind":"policy-brief","programme":"IND","outletUrl":"https://www.competition.org.za/s/IDTT-2022-2023-PB1_Localisation-and-Industrialisation-Nexus.pdf","summary":"A policy brief on how localisation policy connects to industrialisation, and what South Africa can learn from it.","sources":["https://www.competition.org.za/s/IDTT-2022-2023-PB1_Localisation-and-Industrialisation-Nexus.pdf"]}$rita$::jsonb, 'published'),
('opeds', 'more-about-the-melody-less-about-the-volume-financing-industrial', $rita${"title":"More melody, less volume: financing industrial transformation across Africa","outlet":"OPEC Fund Quarterly, 2026 Q2","date":"2026-05","authors":["Ndubuisi","Avenyo"],"kind":"op-ed","programme":"IND","outletUrl":"https://publications.opecfund.org/OFQ-2026-2/8/","summary":"The debate on financing Africa’s green industrial shift focuses too much on the size of the funding gap. The authors argue the deeper constraint is the structure, quality and purpose of finance, and how well it is aligned with industrial development.","sources":["https://publications.opecfund.org/OFQ-2026-2"]}$rita$::jsonb, 'published'),
('opeds', 'no-chips-no-power-why-africa-must-enter-the-global-semiconductor-value', $rita${"title":"No chips, no power: why Africa must enter the global semiconductor value chain","outlet":"Governance & Development Advisory","date":"2026-02","authors":["Ndubuisi"],"kind":"policy-brief","programme":"INN","outletUrl":"https://www.gdadvisory.org/_files/ugd/aeda26_794d17f3e3c44834ae6d49940b25e8c4.pdf","summary":"Africa cannot power its green and digital future without a place in the semiconductor value chain. The brief argues for entering feasible segments, such as chip design, assembly, testing and packaging, and power electronics, collectively through the AfCFTA.","sources":["https://www.gdadvisory.org/blog"]}$rita$::jsonb, 'published'),
('opeds', 'south-africa-is-failing-to-ride-the-digital-revolution-wave-what-it', $rita${"title":"South Africa is failing to ride the digital revolution wave. What it needs to do","outlet":"The Conversation","date":"2021-12","authors":["Avenyo"],"kind":"op-ed","programme":"INN","outletUrl":"https://theconversation.com/south-africa-is-failing-to-ride-the-digital-revolution-wave-what-it-needs-to-do-171515","summary":"A survey of 516 South African firms shows the uptake of digital technologies has been slow and uneven. Premature deindustrialisation has left a small, undiversified production base, which makes it harder to meet the basics: connectivity, energy and digital skills.","sources":["https://newsletter.po.creamermedia.com/article/south-africa-is-failing-to-ride-the-digital-revolution-wave-what-it-needs-to-do-2021-12-03","https://pure.uj.ac.za/en/clippings/why-south-africa-is-failing-to-ride-the-digital-revolution-wave-a/"]}$rita$::jsonb, 'published'),
('opeds', 'south-africas-electricity-crises-have-left-productive-scars-its-green', $rita${"title":"South Africa’s electricity crises have left productive scars. Its green transition must confront them","outlet":"Pan African Visions","date":"2026-07","authors":["Ndubuisi","Avenyo"],"kind":"op-ed","programme":"EN","outletUrl":"https://panafricanvisions.com/2026/07/south-africas-electricity-crises-have-left-productive-scars-its-green-transition-must-confront-them/","summary":"Years of power cuts left productive scars: lost manufacturing capacity, investment, export capability and learning that persist after supply improves. A green transition that ignores them may deliver cleaner electricity while reproducing industrial weakness.","keyPoints":["Outages reduced investment, employment and exports, mainly among electricity-intensive manufacturers.","Reliable power alone will not bring investment back.","Energy reform must become productive reconstruction."],"sources":["https://panafricanvisions.com/2026/07/south-africas-electricity-crises-have-left-productive-scars-its-green-transition-must-confront-them/"]}$rita$::jsonb, 'published'),
('opeds', 'south-africas-path-to-the-4ir-the-role-of-digital-skills', $rita${"title":"South Africa’s path to the 4IR: the role of digital skills","outlet":"Engineering News","date":"2021-03","authors":["Avenyo"],"kind":"op-ed","programme":"INN","outletUrl":"https://www.engineeringnews.co.za/article/opinion-south-africas-path-to-the-4ir-the-role-of-digital-skills-2021-03-04","summary":"For a middle-income technological follower like South Africa, the challenge is to modernise existing capabilities and infrastructure. The Industrial Development Think Tank argues that building digital skills in manufacturing is central to that.","sources":["https://www.engineeringnews.co.za/article/opinion-south-africas-path-to-the-4ir-the-role-of-digital-skills-2021-03-04/searchString:Bell"]}$rita$::jsonb, 'published'),
('opeds', 'technological-capability-and-industrialisation-in-africa', $rita${"title":"Technological capability and industrialisation in Africa","outlet":"SARChI Industrial Development Policy Brief 2024-03","date":"2024-03","authors":["Mensah","Ndubuisi"],"kind":"policy-brief","programme":"INN","outletUrl":"https://www.uj.ac.za/wp-content/uploads/2021/10/sarchi-pb2024-03-mensah-ndubuisi-technological-capability.pdf","summary":"Little is known about how technological capability shapes industrialisation in Africa. The brief measures capability along four dimensions (preconditions, infrastructure, technology imports and technological effort) and shows that capabilities spill over borders through intra-African trade.","sources":["https://uj.ac.za/wp-content/uploads/2021/10/sarchi-pb2024-03-mensah-ndubuisi-technological-capability.pdf"]}$rita$::jsonb, 'published'),
('opeds', 'the-new-era-of-industrial-policy-in-africa-from-sdg-assessment-to', $rita${"title":"The new era of industrial policy in Africa: from SDG assessment to policy solutions","outlet":"UNIDO IID Policy Brief 20","date":"2025-03","authors":["Asiama","Avenyo","Habiyaremye","Ncube","Tregenna","Donnelly","Lavopa"],"kind":"policy-brief","programme":"IND","outletUrl":"https://www.unido.org/publications/policy-briefs","summary":"Linked to the Africa launch of UNIDO’s Industrial Development Report 2024, the brief assesses Africa’s progress on the industry-related SDGs and argues that industrial policy aligned with the SDGs can drive innovation, decent jobs and climate mitigation.","sources":["https://www.unido.org/publications/policy-briefs","https://www.unido.org/news/unido-launches-industrial-development-report-2024-africa"]}$rita$::jsonb, 'published'),
('opeds', 'the-policy-coherence-trap-south-africas-next-industrial-policy-challenge', $rita${"title":"The policy coherence trap: South Africa’s next industrial policy challenge","outlet":"Governance & Development Advisory","date":"2026-09","authors":["Ndubuisi","Avenyo"],"kind":"op-ed","programme":"IND","outletUrl":"https://www.gdadvisory.org/post/the-policy-coherence-trap-south-africa-s-next-industrial-policy-challenge","summary":"South Africa has one of Africa’s most sophisticated industrial policy architectures, yet transformation remains elusive. Aligned strategies and institutions are not enough: coherence must be built around the productive bottlenecks that hold firms back.","sources":["https://www.gdadvisory.org/blog"]}$rita$::jsonb, 'published'),
('opeds', 'trading-for-africas-structural-transformation-why-fit-matters-more', $rita${"title":"Trading for Africa’s structural transformation: why fit matters more","outlet":"Development Front","date":"2026-09","authors":["Ndubuisi","Owusu","Kassa"],"kind":"research-blog","programme":"IND","outletUrl":"https://dev-front.org/trading-for-africas-structural-transformation-why-fit-matters-more/","summary":"Drawing on their study of 52 African countries (2000–2022), the authors argue that what drives structural change is not whether imported inputs come from the North or the South, but how well they fit local capabilities.","sources":["https://onlinelibrary.wiley.com/doi/10.1111/twec.70049"]}$rita$::jsonb, 'published'),
